  payload: Partial<DeploymentRecord> & { id: string }
} | { type: "SET_DEPLOYMENT_RECORDS" payload: DeploymentRecord[] }

const INITIAL_NOTIFICATIONS: Notification[] = []

const INITIAL: AppState = {
  user: null,
  projects: [],
  activeProjectId: null,
  persistenceError: null,
  modal: null,
  confirmPayload: null,
  toasts: [],
  isCommandPaletteOpen: false,
  isShortcutsOpen: false,
  isProfileOpen: false,
  isNotificationsOpen: false,
  notifications: INITIAL_NOTIFICATIONS,
  isForge: false,
  installedSkills: DEFAULT_INSTALLED_SKILL_IDS,
  enabledSkills: DEFAULT_ENABLED_SKILL_IDS,
  connectedConnectors: DEFAULT_CONNECTED_CONNECTOR_IDS,
  deploymentRecords: DEFAULT_DEPLOYMENT_RECORDS,
}

function hydrateInitialState(): AppState {
  const persisted = loadPersistedProjectState()
  const persistedUser = loadPersistedUser()
  // Sanitize persisted projects to remove large HTML/code blobs accidentally
  // stored in message content (one-time defensive hygiene).
  function sanitizePersistedProjects(projects: any[]) {
    if (!Array.isArray(projects)) return projects
    return projects.map((proj) => {
      if (!proj || !Array.isArray(proj.messages)) return proj
      const cleaned = proj.messages.map((m: any) => {
        try {
          const content =
            typeof m.content === "string" ? m.content : String(m.content ?? "")
          const hasHtml = /<[^>]+>/.test(content)
          const overlyLong = content.length > 1200
          const looksLikeCode =
            /function\s*\(|const\s+[a-zA-Z_$]|import\s+\w+|console\.log\(|<script\b/i.test(
              content,
            )
          if (hasHtml || overlyLong || looksLikeCode) {
            return {
              ...m,
              content: "[suppressed preview content]",
              timestamp: m.timestamp ?? new Date().toISOString(),
            }
          }
        } catch {
          // noop
        }
        return m
      })
      return { ...proj, messages: cleaned }
    })
  }
  if (persisted.state && Array.isArray(persisted.state.projects)) {
    const sanitized = sanitizePersistedProjects(persisted.state.projects)
    return {
      ...INITIAL,
      user: persistedUser,
      projects: normalizeProjects(sanitized as any[]),
      activeProjectId: persisted.state.activeProjectId,
      persistenceError: persisted.error ?? null,
    }
  }
  return {
    ...INITIAL,
    user: persistedUser,
    persistenceError: persisted.error ?? null,
  }
}

function reducer(state: AppState, action: Action): AppState {
  switch (action.type) {
    case "SET_USER":
      return { ...state, user: action.payload }
    case "ADD_PROJECT":
      return { ...state, projects: [action.payload, ...state.projects] }
    case "SET_PROJECTS":
      return { ...state, projects: action.payload }
    case "UPDATE_PROJECT":
      return {
        ...state,
        projects: state.projects.map((p) =>
          p.id === action.payload.id
            ? normalizeProject({
                ...p,
                ...action.payload,
                lastEdited: new Date().toISOString(),
                updatedAt: new Date().toISOString(),
              })
            : normalizeProject(p),
        ),
      }
    case "DELETE_PROJECT":
      return {
        ...state,
        projects: state.projects.filter((p) => p.id !== action.payload),
        activeProjectId:
          state.activeProjectId === action.payload
            ? null
            : state.activeProjectId,
      }
    case "STAR_PROJECT":
      return {
        ...state,
        projects: state.projects.map((p) =>
          p.id === action.payload ? { ...p, starred: !p.starred } : p,
        ),
      }
    case "SET_ACTIVE_PROJECT":
      return { ...state, activeProjectId: action.payload }
    case "OPEN_MODAL":
      return { ...state, modal: action.payload }
    case "CLOSE_MODAL":
      return { ...state, modal: null, confirmPayload: null }
    case "SET_CONFIRM":
      return { ...state, confirmPayload: action.payload }
    case "PUSH_TOAST":
      return { ...state, toasts: [...state.toasts.slice(-2), action.payload] }
    case "REMOVE_TOAST":
      return {
        ...state,
        toasts: state.toasts.filter((t) => t.id !== action.payload),
      }
    case "TOGGLE_COMMAND_PALETTE":
      return { ...state, isCommandPaletteOpen: !state.isCommandPaletteOpen }
    case "TOGGLE_SHORTCUTS":
      return { ...state, isShortcutsOpen: !state.isShortcutsOpen }
    case "TOGGLE_PROFILE":
      return { ...state, isProfileOpen: !state.isProfileOpen }
    case "TOGGLE_NOTIFICATIONS":
      return { ...state, isNotificationsOpen: !state.isNotificationsOpen }
    case "ADD_NOTIFICATION":
      return {
        ...state,
        notifications: [action.payload, ...state.notifications],
      }
    case "MARK_ALL_READ":
      return {
        ...state,
        notifications: state.notifications.map((n) => ({ ...n, read: true })),
      }
    case "START_FORGE":
      return { ...state, isForge: true }
    case "END_FORGE":
      return { ...state, isForge: false }
    case "INSTALL_SKILL":
      if (state.installedSkills.includes(action.payload)) return state
      return {
        ...state,
        installedSkills: [...state.installedSkills, action.payload],
        enabledSkills: [...state.enabledSkills, action.payload],
      }
    case "UNINSTALL_SKILL":
      return {
        ...state,
        installedSkills: state.installedSkills.filter(
          (id) => id !== action.payload,
        ),
        enabledSkills: state.enabledSkills.filter(
          (id) => id !== action.payload,
        ),
      }
    case "ENABLE_SKILL":
      if (state.enabledSkills.includes(action.payload)) return state
      return {
        ...state,
        enabledSkills: [...state.enabledSkills, action.payload],
      }
    case "DISABLE_SKILL":
      return {
        ...state,
        enabledSkills: state.enabledSkills.filter(
          (id) => id !== action.payload,
        ),
      }
    case "CONNECT_CONNECTOR":
      if (state.connectedConnectors.includes(action.payload)) return state
      return {
        ...state,
        connectedConnectors: [...state.connectedConnectors, action.payload],
      }
    case "DISCONNECT_CONNECTOR":
      return {
        ...state,
        connectedConnectors: state.connectedConnectors.filter(
          (id) => id !== action.payload,
        ),
      }
    case "ADD_DEPLOYMENT":
      return {
        ...state,
        deploymentRecords: [action.payload, ...state.deploymentRecords],
      }
    case "UPDATE_DEPLOYMENT":
      return {
        ...state,
        deploymentRecords: state.deploymentRecords.map((d) =>
          d.id === action.payload.id ? { ...d, ...action.payload } : d,
        ),
      }
    case "SET_DEPLOYMENT_RECORDS":
      return { ...state, deploymentRecords: action.payload }
    default:
      return state
  }
}

// ─── Context ──────────────────────────────────────────────────────────────────

interface AppContextValue {
  state: AppState
  dispatch: React.Dispatch<Action>
  // Convenience helpers
  toast: (msg: string, type?: Toast["type"], action?: Toast["action"]) => void
  confirm: (payload: ConfirmPayload) => void
  openModal: (m: ModalType) => void
  closeModal: () => void
  createProject: (prompt: string, options?: CreateProjectOptions) => Project
  // Forge
  isForge: boolean
  startForge: () => void
  endForge: () => void
  // Aliases for Phase-based components
  projects: Project[]
  setProjects: (
    projects: Project[] | ((prev: Project[]) => Project[]),
  ) => boolean
  currentUser: User | null
  setCurrentUser: (u: User | null) => void
  setActiveProject: (id: string | null) => void
  persistenceError: string | null
  toasts: Toast[]
  addToast: (msg: string, type?: Toast["type"]) => void
  notifications: Notification[]
  addNotification: (msg: string) => void
  markAllRead: () => void
  commandPaletteOpen: boolean
  setCommandPaletteOpen: (v: boolean | ((prev: boolean) => boolean)) => void
  shortcutOverlayOpen: boolean
  setShortcutOverlayOpen: (v: boolean | ((prev: boolean) => boolean)) => void
  authSheetOpen: boolean
  setAuthSheetOpen: (v: boolean) => void
  // Skills
  installedSkills: string[]
  enabledSkills: string[]
  installSkill: (id: string) => void
  uninstallSkill: (id: string) => void
  enableSkill: (id: string) => void
  disableSkill: (id: string) => void
  isSkillInstalled: (id: string) => boolean
  isSkillEnabled: (id: string) => boolean
  // Connectors
  connectedConnectors: string[]
  connectConnector: (id: string) => void
  disconnectConnector: (id: string) => void
  isConnectorConnected: (id: string) => boolean
  // Deployments
  deploymentRecords: DeploymentRecord[]
  addDeployment: (record: DeploymentRecord) => void
  updateDeployment: (id: string, update: Partial<DeploymentRecord>) => void
  // Workspace Editing
  updateWorkspaceFile: (path: string, content: string) => boolean
  // Usage metering
  usageMeter: UsagePeriod
  setPlan: (plan: "free" | "pro") => void
  // Server project sync
  loadServerProjects: () => Promise<void>
}

const AppContext = createContext<AppContextValue | null>(null)

function createFallbackProject(): Project {
  const now = new Date().toISOString()
  return {
    id: "",
    name: "Untitled project",
    description: "",
    status: "DRAFT",
    lastEdited: now,
    updatedAt: now,
    createdAt: now,
    starred: false,
    messages: [],
    versions: [],
  }
}

export function applyGenerationResultToProjects(
  projects: Project[],
  projectId: string,
  result: GenerationResult,
  completedAt: string,
  mode: "plan" | "build" = "build",
): Project[] {
  return projects.map((project) => {
    if (project.id !== projectId) return project

    const assistantMessage: ChatMessage = {
      id: generateId(),
      role: "assistant",
      content: result.assistant,
      timestamp: completedAt,
      pending: false,
    }

    const pendingIndex = project.messages.findIndex(
      (message) => message.role === "assistant" && message.pending,
    )
    const nextMessages =
      pendingIndex >= 0
        ? project.messages.map((message, index) =>
            index === pendingIndex
              ? { ...message, ...assistantMessage, pending: false }
              : message,
          )
        : [...project.messages, assistantMessage]

    if (mode === "plan") {
      return {
        ...project,
        lastEdited: completedAt,
        updatedAt: completedAt,
        messages: nextMessages,
        providerDiagnostics: result.diagnostics
          ? typeof result.diagnostics === "string"
            ? result.diagnostics
            : JSON.stringify(result.diagnostics)
          : project.providerDiagnostics,
      }
    }

    const artifactSnapshot = result.artifact
      ? { ...result.artifact, createdAt: completedAt }
      : project.artifact
    const derivedWorkspaceFiles = mergeWorkspaceFilesWithArtifact(
      project.files,
      artifactSnapshot,
      completedAt,
    )
    const derivedArtifact = deriveProjectArtifact(
      { ...project, files: derivedWorkspaceFiles, artifact: artifactSnapshot },
      completedAt,
    )
    const versions = project.versions.map((version) => {
      if (!version.isCurrent) return version
      return {
        ...version,
        artifact: derivedArtifact ?? version.artifact,
        assistantMessage: result.assistant,
      }
    })

    return {
      ...project,
      lastEdited: completedAt,
      updatedAt: completedAt,
      messages: nextMessages,
      files: derivedWorkspaceFiles,
      artifact: derivedArtifact,
      versions,
      providerDiagnostics: result.diagnostics
        ? typeof result.diagnostics === "string"
          ? result.diagnostics
          : JSON.stringify(result.diagnostics)
        : project.providerDiagnostics,
    }
  })
}

const fallbackContextValue: AppContextValue = {
  state: INITIAL,
  dispatch: () => undefined,
  toast: () => undefined,
  confirm: () => undefined,
  openModal: () => undefined,
  closeModal: () => undefined,
  createProject: () => createFallbackProject(),
  isForge: false,
  startForge: () => undefined,
  endForge: () => undefined,
  projects: [],
  setProjects: () => true,
  currentUser: null,
  setCurrentUser: () => undefined,
  setActiveProject: () => undefined,
  persistenceError: null,
  toasts: [],
  addToast: () => undefined,
  notifications: [],
  addNotification: () => undefined,
  markAllRead: () => undefined,
  commandPaletteOpen: false,
  setCommandPaletteOpen: () => undefined,
  shortcutOverlayOpen: false,
  setShortcutOverlayOpen: () => undefined,
  authSheetOpen: false,
  setAuthSheetOpen: () => undefined,
  installedSkills: DEFAULT_INSTALLED_SKILL_IDS,
  enabledSkills: DEFAULT_ENABLED_SKILL_IDS,
  installSkill: () => undefined,
  uninstallSkill: () => undefined,
  enableSkill: () => undefined,
  disableSkill: () => undefined,
  isSkillInstalled: () => false,
  isSkillEnabled: () => false,
  connectedConnectors: DEFAULT_CONNECTED_CONNECTOR_IDS,
  connectConnector: () => undefined,
  disconnectConnector: () => undefined,
  isConnectorConnected: () => false,
  deploymentRecords: DEFAULT_DEPLOYMENT_RECORDS,
  addDeployment: () => undefined,
  updateDeployment: () => undefined,
  updateWorkspaceFile: () => false,
  usageMeter: readUsagePeriod("free"),
  setPlan: () => undefined,
  loadServerProjects: () => Promise.resolve(),
}

export function AppProvider({ children }: { children: ReactNode }) {
  const [state, dispatch] = useReducer(reducer, undefined, hydrateInitialState)
  const stateRef = useRef(state)
  stateRef.current = state

  // Usage metering — seeded from persisted localStorage; updated on each generation.
  const [usageMeter, setUsageMeter] = useState<UsagePeriod>(() =>
    readUsagePeriod((loadPersistedUser()?.plan ?? "free") as "free" | "pro"),
  )

  useEffect(() => {
    let mounted = true
    void (async () => {
      try {
        const response = await fetch("/api/deployments")
        if (!response.ok) throw new Error("Unable to load deployments")
        const body = await response.json().catch(() => null)
        const remoteDeployments = Array.isArray(body)
          ? body
          : Array.isArray(body?.deployments)
            ? body.deployments
            : []
        if (!mounted) return
        if (remoteDeployments.length > 0) {
          dispatch({
            type: "SET_DEPLOYMENT_RECORDS",
            payload: normalizeDeploymentRecords(
              remoteDeployments,
              DEFAULT_DEPLOYMENT_RECORDS,
            ),
          })
        }
      } catch {
        // keep seeded deployment history when the backend is unavailable
      }
    })()
    return () => {
      mounted = false
    }
  }, [])

  // Bootstrap user and projects from server session cookie on mount.
  // If the server recognises the cookie the client user state is updated to
  // match, and the user's server-side projects are merged into local state —
  // giving cross-session project continuity without requiring the builder to
  // re-enter credentials or lose work after a page refresh.
  // Failures are silent — the user stays unauthenticated and local state is kept.
  useEffect(() => {
    let mounted = true
    void (async () => {
      try {
        const res = await fetch("/api/auth/session", {
          credentials: "same-origin",
        })
        if (!res.ok || !mounted) return
        const body = await res.json().catch(() => null)
        if (!mounted) return
        const raw = body?.user
        if (
          !raw ||
          typeof raw.name !== "string" ||
          typeof raw.email !== "string"
        )
          return
        const serverUser: User = {
          name: raw.name,
          email: raw.email,
          avatar: typeof raw.avatar === "string" ? raw.avatar : "",
          plan: raw.plan === "pro" ? "pro" : "free",
        }
        // Only update if the server user differs from what's already loaded
        // (avoid a redundant re-render on every mount when localStorage matches)
        const current = stateRef.current.user
        if (
          !current ||
          current.email !== serverUser.email ||
          current.plan !== serverUser.plan
        ) {
          dispatch({ type: "SET_USER", payload: serverUser })
          savePersistedUser(serverUser)
          setUsageMeter(readUsagePeriod(serverUser.plan))
        }

        // Fetch this user's server-side projects and merge into local state.
        // mergePersistedProjects: remote wins for non-in-flight projects;
        // local wins for projects currently generating.
        try {
          const projRes = await fetch("/api/projects", {
            credentials: "same-origin",
          })
          if (!projRes.ok || !mounted) return
          const projBody = await projRes.json().catch(() => null)
          if (!mounted) return
          const remote: unknown[] = Array.isArray(projBody?.projects)
            ? projBody.projects
            : Array.isArray(projBody)
              ? projBody
              : []
          if (remote.length > 0) {
            const next = normalizeProjects(
              mergePersistedProjects(
                stateRef.current.projects,
                remote as any[],
              ),
            )
            dispatch({ type: "SET_PROJECTS", payload: next })
            stateRef.current = { ...stateRef.current, projects: next }
            // Persist merged state locally so the next cold-start is accurate
            saveProjectStateSnapshot(next, stateRef.current.activeProjectId)
          }
        } catch {
          // project fetch failed — continue with local state
        }
      } catch {
        // session endpoint unavailable — continue with persisted state
      }
    })()
    return () => {
      mounted = false
    }
  }, [])

  const toast = useCallback(
    (
      msg: string,
      type: Toast["type"] = "default",
      action?: Toast["action"],
    ) => {
      const id = generateId()
      dispatch({
        type: "PUSH_TOAST",
        payload: { id, message: msg, type, action },
      })
      setTimeout(() => dispatch({ type: "REMOVE_TOAST", payload: id }), 4000)
    },
    [],
  )

  const confirm = useCallback((payload: ConfirmPayload) => {
    dispatch({ type: "SET_CONFIRM", payload })
    dispatch({ type: "OPEN_MODAL", payload: "confirm" })
  }, [])

  const openModal = useCallback(
    (m: ModalType) => dispatch({ type: "OPEN_MODAL", payload: m }),
    [],
  )
  const closeModal = useCallback(() => dispatch({ type: "CLOSE_MODAL" }), [])

  const createProject = useCallback(
    (prompt: string, options: CreateProjectOptions = {}): Project => {
      const now = new Date().toISOString()
      const generationMode = options.mode ?? "build"
      const userMessage: ChatMessage = {
        id: generateId(),
        role: "user",
        content: prompt,
        timestamp: now,
      }
      const pendingAssistantMessage: ChatMessage = {
        id: generateId(),
        role: "assistant",
        content: "Preparing your workspace and drafting the first version…",
        timestamp: now,
        pending: true,
      }
      const p: Project = {
        id: generateId(),
        name: options.name?.trim().slice(0, 48) || prompt.slice(0, 48),
        description: options.description?.trim() ?? "",
        status: "DRAFT",
        lastEdited: now,
        updatedAt: now,
        createdAt: now,
        starred: false,
        messages: [userMessage, pendingAssistantMessage],
        versions:
          generationMode === "build"
            ? [
                {
                  id: generateId(),
                  number: 1,
                  label:
                    options.name?.trim().slice(0, 48) || prompt.slice(0, 48),
                  timestamp: now,
                  prompt,
                  isCurrent: true,
                  createdAt: now,
                  trigger: { type: "initial-generation", prompt },
                },
              ]
            : [],
        initialPrompt: prompt,
        template: options.template,
        // Mark in-flight so mergePersistedProjects does not overwrite this project
        // with a stale remote snapshot while generation is running.
        generatingAt: now,
      }
      const nextProjects = [
        normalizeProject(p),
        ...normalizeProjects(stateRef.current.projects),
      ]
      const persisted = saveProjectStateSnapshot(nextProjects, p.id)
      if (!persisted.ok) {
        toast(persisted.error, "error")
        return p
      }
      dispatch({ type: "ADD_PROJECT", payload: p })
      dispatch({ type: "SET_ACTIVE_PROJECT", payload: p.id })
      stateRef.current = {
        ...stateRef.current,
        projects: nextProjects,
        activeProjectId: p.id,
      }

      // Persist project to dev backend (best-effort, non-blocking)
      void (async () => {
        try {
          await fetch("/api/projects", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
              clientId: p.id,
              name: p.name,
              description: p.description,
              status: p.status,
              messages: p.messages,
              versions: p.versions,
              initialPrompt: p.initialPrompt,
              template: p.template,
              createdAt: p.createdAt,
              updatedAt: p.updatedAt,
            }),
          }).then(async (res) => {
            if (!res.ok) {
              const txt = await res.text()
              toast(`Project persist failed: ${res.status} ${txt}`, "error")
              return
            }
            const serverProject = await res.json()
            // attach server id for diagnostics without replacing the local id
            setProjects((prev) =>
              prev.map((proj) =>
                proj.id === p.id
                  ? {
                      ...proj, // eslint-disable-line @typescript-eslint/ban-ts-comment
                      // store remote id for tracing
                      // @ts-ignore
                      serverId: serverProject.id,
                    }
                  : proj,
              ),
            )
          })
        } catch (err) {
          // non-fatal
        }
      })()

      // Kick off generation request — keep optimistic local id stable until generation completes
      void (async () => {
        try {
          const result = await generateProjectResponse(prompt, {
            model: options.model,
            mode: options.mode,
          })
          const completedAt = new Date().toISOString()
          // Record one generation credit against the billing period.
          const plan = (stateRef.current.user?.plan ?? "free") as "free" | "pro"
          setUsageMeter(recordGeneration(plan))
          // Clear generatingAt on success so mergePersistedProjects can resume normal sync
          const updateSucceeded = setProjects((prev) => {
            const withCleared = prev.map((proj) =>
              proj.id === p.id ? { ...proj, generatingAt: undefined } : proj,
            )
            return applyGenerationResultToProjects(
              withCleared,
              p.id,
              result,
              completedAt,
              options.mode ?? "build",
            )
          })
          if (!updateSucceeded) {
            toast("Unable to persist the generated project update.", "error")
          }
          addToast(
            result.usedFallback
              ? "Plan generated with fallback"
              : options.mode === "plan"
                ? "Plan ready"
                : "Project generated",
            result.usedFallback ? "default" : "success",
          )
        } catch (error) {
          const message =
            error instanceof Error ? error.message : "Generation failed"
          const applyFailure = (projects: Project[]): Project[] =>
            projects.map((project) => {
              if (project.id !== p.id) return project
              const assistantMessage: ChatMessage = {
                id: generateId(),
                role: "assistant",
                content:
                  "The generation request could not be completed. Please try again.",
                timestamp: new Date().toISOString(),
              }
              return {
                ...project,
                lastEdited: now,
                updatedAt: now,
                messages: [...project.messages, assistantMessage],
                // Clear generatingAt on failure so future syncs can proceed normally
                generatingAt: undefined,
              }
            })
          const updateSucceeded = setProjects((prev) => applyFailure(prev))
          if (!updateSucceeded) {
            toast("Unable to persist the failed generation update.", "error")
          }
          addToast(message, "error")
        }
      })()

      return p
    },
    [state.projects, toast],
  )

  const startForge = useCallback(() => dispatch({ type: "START_FORGE" }), [])
  const endForge = useCallback(() => dispatch({ type: "END_FORGE" }), [])
  const setCurrentUser = useCallback(
    (u: User | null) => {
      dispatch({ type: "SET_USER", payload: u })
      const persisted = savePersistedUser(u)
      if (!persisted.ok) {
        toast(persisted.error, "error")
      }
    },
    [toast],
  )
  const addToast = useCallback(
    (msg: string, type: Toast["type"] = "default") => toast(msg, type),
    [toast],
  )
  const addNotification = useCallback((msg: string) => {
    dispatch({
      type: "ADD_NOTIFICATION",
      payload: {
        id: generateId(),
        message: msg,
        read: false,
        timestamp: new Date().toISOString(),
      },
    })
  }, [])
  const markAllRead = useCallback(() => dispatch({ type: "MARK_ALL_READ" }), [])
  const setActiveProject = useCallback(
    (id: string | null) => {
      const resolvedId =
        id && stateRef.current.projects.some((project) => project.id === id)
          ? id
          : null
      dispatch({ type: "SET_ACTIVE_PROJECT", payload: resolvedId })
      stateRef.current = { ...stateRef.current, activeProjectId: resolvedId }

      const persisted = saveProjectStateSnapshot(
        stateRef.current.projects,
        resolvedId,
      )
      if (!persisted.ok) {
        toast(persisted.error, "error")
      }
    },
    [toast],
  )
  const setProjects = useCallback(
    (updater: Project[] | ((prev: Project[]) => Project[])): boolean => {
      const currentProjects = stateRef.current.projects
      const next = normalizeProjects(
        typeof updater === "function" ? updater(currentProjects) : updater,
      )
      const prevActiveProjectId = stateRef.current.activeProjectId
      const nextActiveProjectId =
        prevActiveProjectId &&
        !next.some((project) => project.id === prevActiveProjectId)
          ? null
          : prevActiveProjectId

      dispatch({ type: "SET_PROJECTS", payload: next })
      if (nextActiveProjectId !== prevActiveProjectId) {
        dispatch({ type: "SET_ACTIVE_PROJECT", payload: nextActiveProjectId })
      }
      stateRef.current = {
        ...stateRef.current,
        projects: next,
        activeProjectId: nextActiveProjectId,
      }

      const persisted = saveProjectStateSnapshot(next, nextActiveProjectId)
      if (!persisted.ok) {
        toast(persisted.error, "error")
        return false
      }

      // Best-effort dev backend sync for project persistence.
      void (async () => {
        try {
          await fetch("/api/projects", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(next),
          })
        } catch {
          // ignore remote sync failures in dev mode
        }
      })()

      return true
    },
    [toast],
  )
  const setCommandPaletteOpen = useCallback(
    (v: boolean | ((prev: boolean) => boolean)) => {
      const next = typeof v === "function" ? v(state.isCommandPaletteOpen) : v
      if (next !== state.isCommandPaletteOpen)
        dispatch({ type: "TOGGLE_COMMAND_PALETTE" })
    },
    [state.isCommandPaletteOpen],
  )
  const setShortcutOverlayOpen = useCallback(
    (v: boolean | ((prev: boolean) => boolean)) => {
      const next = typeof v === "function" ? v(state.isShortcutsOpen) : v
      if (next !== state.isShortcutsOpen) dispatch({ type: "TOGGLE_SHORTCUTS" })
    },
    [state.isShortcutsOpen],
  )
  const setAuthSheetOpen = useCallback((v: boolean) => {
    if (v) dispatch({ type: "OPEN_MODAL", payload: "auth" })
    else dispatch({ type: "CLOSE_MODAL" })
  }, [])

  const installSkill = useCallback(
    (id: string) => dispatch({ type: "INSTALL_SKILL", payload: id }),
    [],
  )
  const uninstallSkill = useCallback(
    (id: string) => dispatch({ type: "UNINSTALL_SKILL", payload: id }),
    [],
  )
  const enableSkill = useCallback(
    (id: string) => dispatch({ type: "ENABLE_SKILL", payload: id }),
    [],
  )
  const disableSkill = useCallback(
    (id: string) => dispatch({ type: "DISABLE_SKILL", payload: id }),
    [],
  )
  const isSkillInstalled = useCallback(
    (id: string) => state.installedSkills.includes(id),
    [state.installedSkills],
  )
  const isSkillEnabled = useCallback(
    (id: string) => state.enabledSkills.includes(id),
    [state.enabledSkills],
  )

  const connectConnector = useCallback(
    (id: string) => dispatch({ type: "CONNECT_CONNECTOR", payload: id }),
    [],
  )
  const disconnectConnector = useCallback(
    (id: string) => dispatch({ type: "DISCONNECT_CONNECTOR", payload: id }),
    [],
  )
  const isConnectorConnected = useCallback(
    (id: string) => state.connectedConnectors.includes(id),
    [state.connectedConnectors],
  )

  const addDeployment = useCallback(
    (record: DeploymentRecord) =>
      dispatch({ type: "ADD_DEPLOYMENT", payload: record }),
    [],
  )
  const updateDeployment = useCallback(
    (id: string, update: Partial<DeploymentRecord>) =>
      dispatch({ type: "UPDATE_DEPLOYMENT", payload: { ...update, id } }),
    [],
  )

  const updateWorkspaceFile = useCallback(
    (path: string, content: string): boolean => {
      const activeId = stateRef.current.activeProjectId
      if (!activeId) return false
      const now = new Date().toISOString()

      return setProjects((prev) =>
        prev.map((p) => {
          if (p.id !== activeId) return p
          const updatedFiles = updateProjectFile(p.files, path, content, now)
          const updatedProject = {
            ...p,
            files: updatedFiles,
            lastEdited: now,
            updatedAt: now,
          }
          const derivedArtifact = deriveProjectArtifact(updatedProject, now)
          return {
            ...updatedProject,
            artifact: derivedArtifact,
          }
        }),
      )
    },
    [setProjects],
  )

  const setPlan = useCallback((plan: "free" | "pro") => {
    const current = stateRef.current.user
    if (!current) return
    const updated: User = { ...current, plan }
    dispatch({ type: "SET_USER", payload: updated })
    savePersistedUser(updated)
    setUsageMeter(readUsagePeriod(plan))
  }, [])

  const loadServerProjects = useCallback(async () => {
    try {
      const res = await fetch("/api/projects", { credentials: "same-origin" })
      if (!res.ok) return
      const body = await res.json().catch(() => null)
      const remote: unknown[] = Array.isArray(body?.projects)
        ? body.projects
        : Array.isArray(body)
          ? body
          : []
      if (remote.length === 0) return
      const next = normalizeProjects(
        mergePersistedProjects(stateRef.current.projects, remote as any[]),
      )
      dispatch({ type: "SET_PROJECTS", payload: next })
      stateRef.current = { ...stateRef.current, projects: next }
      saveProjectStateSnapshot(next, stateRef.current.activeProjectId)
    } catch {
      // network unavailable — keep local state
    }
  }, [])

  const value: AppContextValue = {
    state,
    dispatch,
    toast,
    confirm,
    openModal,
    closeModal,
    createProject,
    isForge: state.isForge,
    startForge,
    endForge,
    projects: state.projects,
    setProjects,
    currentUser: state.user,
    setCurrentUser,
    setActiveProject,
    persistenceError: state.persistenceError,
    toasts: state.toasts,
    addToast,
    notifications: state.notifications,
    addNotification,
    markAllRead,
    commandPaletteOpen: state.isCommandPaletteOpen,
    setCommandPaletteOpen,
    shortcutOverlayOpen: state.isShortcutsOpen,
    setShortcutOverlayOpen,
    authSheetOpen: state.modal === "auth",
    setAuthSheetOpen,
    installedSkills: state.installedSkills,
    enabledSkills: state.enabledSkills,
    installSkill,
    uninstallSkill,
    enableSkill,
    disableSkill,
    isSkillInstalled,
    isSkillEnabled,
    connectedConnectors: state.connectedConnectors,
    connectConnector,
    disconnectConnector,
    isConnectorConnected,
    deploymentRecords: state.deploymentRecords,
    addDeployment,
    updateDeployment,
    updateWorkspaceFile,
    usageMeter,
    setPlan,
    loadServerProjects,
  }

  return <AppContext.Provider value={value}>{children}</AppContext.Provider>
}

export function useApp() {
  const context = useContext(AppContext)
  return context ?? fallbackContextValue
}

import {
  createArtifactFromHtmlResponse,
  createGeneratedArtifact,
  type GeneratedArtifact,
} from "./generatedArtifact"
import { buildWorkspaceContext, type WorkspaceContext } from "./contextBuilder"
import type { GenerationProvenance, ProjectArtifact } from "./store"

export interface GenerationFileChange {
  path: string
  operation: "create" | "modify" | "delete"
  content?: string
  language?: string
}

export interface GenerationResult {
  // human-readable assistant text (sanitized)
  assistant: string
  // raw provider string (may include code/html)
  raw: string
  provider: string
  model?: string
  usedFallback: boolean
  artifact: GeneratedArtifact
  fileChanges?: GenerationFileChange[]
  // non-secret diagnostics returned by server/provider (optional)
  diagnostics?: string | Record<string, unknown>
  provenance?: GenerationProvenance
}

const VITEST_DEBUG = import.meta.env.VITE_VITEST_DEBUG === "true"

export interface WorkspaceFileContextEntry {
  path: string
  content: string
  language?: string
}

export interface GenerationOptions {
  signal?: AbortSignal
  previousArtifact?: ProjectArtifact | GeneratedArtifact
  previousPrompt?: string
  mode?: "plan" | "build"
  model?: string
  language?: string
  projectId?: string
  activeFile?: string
  enabledSkills?: Array<{ id: string name: string purpose: string }>
  workspaceFiles?: WorkspaceFileContextEntry[]
  workspaceContext?: WorkspaceContext
  onEvent?: (event: {
    type: string
    content?: string
    message?: string
    file?: unknown
    version?: unknown
    data?: unknown
  }) => void
}

export function resolveGenerationMode(isPlanMode: boolean): "plan" | "build" {
  return isPlanMode ? "plan" : "build"
}

export interface GenerationPreferences {
  mode: "plan" | "build"
  model: string
  language: string
}

export function resolveGenerationPreferences(
  storage: Pick<Storage, "getItem"> = typeof window !== "undefined"
    ? window.localStorage
    : { getItem: () => null },
): GenerationPreferences {
  const savedMode = storage.getItem("shango_generation_mode")
  const isPlanMode = savedMode === "plan"
  const settings = (() => {
    try {
      const raw = storage.getItem("shango_settings")
      return raw ? JSON.parse(raw) : {}
    } catch {
      return {}
    }
  })()
  const model =
    typeof settings?.model === "string" && settings.model.trim()
      ? settings.model
      : "balanced"
  const language =
    typeof settings?.language === "string" && settings.language.trim()
      ? settings.language
      : "English"

  return {
    mode: resolveGenerationMode(isPlanMode),
    model,
    language,
  }
}

function isValidArtifactPayload(
  payload: unknown,
): payload is GeneratedArtifact {
  return (
    typeof payload === "object" &&
    payload !== null &&
    typeof (payload as any).html === "string" &&
    typeof (payload as any).css === "string" &&
    typeof (payload as any).js === "string" &&
    typeof (payload as any).title === "string" &&
    typeof (payload as any).description === "string"
  )
}

function tryParseArtifactCandidate(
  candidate: string,
): GeneratedArtifact | null {
  try {
    const parsed = JSON.parse(candidate)
    if (isValidArtifactPayload(parsed)) return parsed
    if (typeof parsed === "string") {
      const nested = JSON.parse(parsed)
      if (isValidArtifactPayload(nested)) return nested
    }
  } catch {
    // ignore parse failures
  }
  return null
}

function extractQuotedJsonArtifact(
  source: string,
): { artifact?: GeneratedArtifact assistantText: string } | null {
  const trimmed = source.trim()

  if (VITEST_DEBUG) {
    console.log("extractQuotedJsonArtifact source:", JSON.stringify(source))
    console.log("extractQuotedJsonArtifact trimmed:", JSON.stringify(trimmed))
  }

  for (let startIndex = 0; startIndex < source.length; startIndex += 1) {
    if (source[startIndex] !== '"') continue

    let jsonStart = startIndex + 1
    while (jsonStart < source.length && source[jsonStart].trim() === "") {
      jsonStart += 1
    }

    if (source[jsonStart] !== "{") continue

    let depth = 0
    let inString = false
    let escape = false
    let endIndex = -1

    for (let i = jsonStart; i < source.length; i += 1) {
      const char = source[i]
      if (escape) {
        escape = false
        continue
      }
      if (char === "\\") {
        if (inString) escape = true
        continue
      }
      if (char === '"') {
        inString = !inString
        continue
      }
      if (inString) continue
      if (char === "{") {
        depth += 1
        continue
      }
      if (char === "}") {
        depth -= 1
        if (depth === 0) {
          endIndex = i
          break
        }
      }
    }

    if (endIndex < 0) continue

    let closingQuote = endIndex + 1
    while (closingQuote < source.length && source[closingQuote].trim() === "") {
      closingQuote += 1
    }

    if (closingQuote >= source.length || source[closingQuote] !== '"') continue

    const candidate = source.slice(jsonStart, endIndex + 1)
    if (VITEST_DEBUG) {
      console.log(
        "extractQuotedJsonArtifact candidate:",
        JSON.stringify(candidate),
      )
      console.log(
        "extractQuotedJsonArtifact indexes:",
        startIndex,
        jsonStart,
        endIndex,
        closingQuote,
      )
    }

    const artifact = tryParseArtifactCandidate(candidate)
    if (artifact) {
      if (VITEST_DEBUG)
        console.log("extractQuotedJsonArtifact artifact found", artifact)
      const assistantText =
        `${trimmed.slice(0, startIndex)}${trimmed.slice(closingQuote + 1)}`.trim()
      return { artifact, assistantText }
    }
  }

  if (VITEST_DEBUG) console.log("extractQuotedJsonArtifact no artifact found")
  return null
}

function removeFencedBlock(source: string, block: string): string {
  return source
    .replace(block, "")
    .replace(/```[\w-]*\s*/g, "")
    .replace(/```/g, "")
    .trim()
}

function extractJsonArtifactFromText(
  source: string,
): { artifact?: GeneratedArtifact assistantText: string } {
  const normalized = source
    .replace(/```(?:json|html|htm|xml|markup|javascript|js|css)?\s*|```/g, "")
    .trim()
  if (!normalized) return { assistantText: "" }

  const directArtifact = tryParseArtifactCandidate(normalized)
  if (directArtifact) {
    return { artifact: directArtifact, assistantText: "" }
  }

  let inString = false
  let escape = false
  let depth = 0
  let startIndex = -1

  for (let i = 0; i < normalized.length; i += 1) {
    const char = normalized[i]
    if (escape) {
      escape = false
      continue
    }

    if (char === "\\") {
      if (inString) escape = true
      continue
    }

    if (char === '"') {
      inString = !inString
      continue
    }

    if (inString) continue

    if (char === "{") {
      if (depth === 0) startIndex = i
      depth += 1
      continue
    }

    if (char === "}") {
      depth -= 1
      if (depth === 0 && startIndex >= 0) {
        const candidate = normalized.slice(startIndex, i + 1)
        const artifact = tryParseArtifactCandidate(candidate)
        if (artifact) {
          const assistantText =
            `${normalized.slice(0, startIndex)}${normalized.slice(i + 1)}`.trim()
          return { artifact, assistantText }
        }
      }
    }
  }

  return { assistantText: normalized }
}

function normalizeDiagnostics(
  value: unknown,
): string | Record<string, unknown> | undefined {
  if (typeof value === "string") return value
  if (value && typeof value === "object" && !Array.isArray(value)) {
    return value as Record<string, unknown>
  }
  return undefined
}

function normalizeProvenance(value: unknown): GenerationProvenance | undefined {
  if (!value || typeof value !== "object" || Array.isArray(value))
    return undefined

  const record = value as Record<string, unknown>
  const id = typeof record.id === "string" ? record.id : undefined
  const timestamp =
    typeof record.timestamp === "string" ? record.timestamp : undefined
  const provider =
    typeof record.provider === "string" ? record.provider : undefined
  const prompt = typeof record.prompt === "string" ? record.prompt : undefined
  const mode =
    record.mode === "plan" || record.mode === "build" ? record.mode : undefined

  if (!id || !timestamp || !provider || !prompt || !mode) return undefined

  const operations = Array.isArray(record.operations)
    ? record.operations.reduce<GenerationProvenance["operations"]>(
        (accepted, item) => {
          if (!item || typeof item !== "object") return accepted
          const operation = item as Record<string, unknown>
          const path =
            typeof operation.path === "string" ? operation.path : undefined
          const normalizedOperation =
            operation.operation === "create" ||
            operation.operation === "modify" ||
            operation.operation === "delete"
              ? operation.operation as GenerationProvenance["operations"][number]["operation"]
              : "modify"
          if (path) accepted.push({ path, operation: normalizedOperation })
          return accepted
        },
        [],
      )
    : []

  const rejectedOperations = Array.isArray(record.rejectedOperations)
    ? record.rejectedOperations.reduce<NonNullable<GenerationProvenance["rejectedOperations"]>>(
        (rejected, item) => {
          if (!item || typeof item !== "object") return rejected
          const operation = item as Record<string, unknown>
          const reason =
            operation.reason === "invalid-path" ||
            operation.reason === "protected-file"
              ? operation.reason
              : undefined
          const path =
            typeof operation.path === "string" ? operation.path : undefined
          if (path && reason) rejected.push({ path, reason })
          return rejected
        },
        [],
      )
    : undefined

  const skills = Array.isArray(record.skills)
    ? record.skills.reduce<Array<{ id: string name: string purpose: string }>>(
        (accepted, item) => {
          if (!item || typeof item !== "object") return accepted
          const skill = item as Record<string, unknown>
          if (
            typeof skill.id === "string" &&
            typeof skill.name === "string" &&
            typeof skill.purpose === "string"
          )
            accepted.push({
              id: skill.id,
              name: skill.name,
              purpose: skill.purpose,
            })
          return accepted
        },
        [],
      )
    : undefined

  return {
    id,
    timestamp,
    provider,
    model: typeof record.model === "string" ? record.model : undefined,
    mode,
    prompt,
    operations,
    rejectedOperations: rejectedOperations?.length
      ? rejectedOperations
      : undefined,
    skills,
  }
}

function normalizeModelSelection(model?: string): string {
  const normalized = typeof model === "string" ? model.trim().toLowerCase() : ""
  if (normalized === "deep") return "powerful"
  if (
    normalized === "fast" ||
    normalized === "balanced" ||
    normalized === "powerful"
  )
    return normalized
  return "balanced"
}

function normalizeFileChange(value: unknown): GenerationFileChange | null {
  if (!value || typeof value !== "object" || Array.isArray(value)) return null

  const record = value as Record<string, unknown>
  const path = typeof record.path === "string" ? record.path.trim() : ""
  if (!path) return null

  const operation =
    record.operation === "delete"
      ? "delete"
      : record.operation === "create"
        ? "create"
        : "modify"
  return {
    path,
    operation,
    content: typeof record.content === "string" ? record.content : undefined,
    language: typeof record.language === "string" ? record.language : undefined,
  }
}

function normalizeFileChanges(value: unknown): GenerationResult["fileChanges"] {
  if (!Array.isArray(value)) return undefined

  return value.reduce<GenerationFileChange[]>((acc, item) => {
    const change = normalizeFileChange(item)
    if (change) acc.push(change)
    return acc
  }, [])
}

function buildArtifactFromStructuredBuild(
  payload: unknown,
  prompt: string,
): GeneratedArtifact | null {
  if (!payload || typeof payload !== "object" || Array.isArray(payload))
    return null

  const container = payload as Record<string, unknown>
  const files = Array.isArray(container.build)
    ? undefined
    : (container.build as {
        files?: Array<Record<string, unknown>>
      } | undefined)?.files
  if (!Array.isArray(files)) return null

  let html = ""
  let css = ""
  let js = ""

  for (const file of files) {
    if (!file || typeof file !== "object") continue
    const content = typeof file.content === "string" ? file.content : ""
    const path = typeof file.path === "string" ? file.path.toLowerCase() : ""
    const language =
      typeof file.language === "string" ? file.language.toLowerCase() : ""

    if (
      content &&
      (path.endsWith(".html") || path.endsWith(".htm") || language === "html")
    ) {
      html = content
    } else if (content && (path.endsWith(".css") || language === "css")) {
      css = content
    } else if (
      content &&
      (path.endsWith(".js") ||
        path.endsWith(".ts") ||
        path.endsWith(".tsx") ||
        path.endsWith(".jsx") ||
        language === "javascript" ||
        language === "typescript" ||
        language === "tsx" ||
        language === "jsx")
    ) {
      js = content
    }
  }

  if (!html && !css && !js) return null

  const title = prompt.trim() ? prompt.trim().slice(0, 60) : "Structured Build"
  const description = html
    ? "Generated from the structured build response."
    : "Generated from the structured build response."
  return {
    html: html || `<main><h1>${title}</h1><p>${description}</p></main>`,
    css:
      css ||
      `:root { color-scheme: dark; font-family: Inter, system-ui, sans-serif; } body { margin: 0; padding: 2rem; background: #0b1020; color: #f8fafc; } main { max-width: 720px; margin: 0 auto; }`,
    js: js || `console.log('Structured build artifact ready');`,
    title,
    description,
    createdAt: new Date().toISOString(),
  }
}

function extractArtifactPayload(
  raw: string,
  prompt: string,
): {
  artifact?: GeneratedArtifact
  assistantText: string
  usedFallback: boolean
} {
  const trimmed = raw.trim()
  if (!trimmed) return { assistantText: "", usedFallback: true }

  if (VITEST_DEBUG) {
    console.log("extractArtifactPayload raw:", JSON.stringify(raw))
    console.log("extractArtifactPayload trimmed:", JSON.stringify(trimmed))
  }

  const directJsonArtifact = tryParseArtifactCandidate(trimmed)
  if (directJsonArtifact) {
    if (VITEST_DEBUG) console.log("directJsonArtifact OK", directJsonArtifact)
    return {
      artifact: directJsonArtifact,
      assistantText: "",
      usedFallback: false,
    }
  }

  const fencedBlocks = Array.from(
    trimmed.matchAll(
      /```(?:json|html|htm|xml|markup|javascript|js|css)?\s*([\s\S]*?)```/gi,
    ),
  )
  for (const match of fencedBlocks) {
    const candidate = match[1]?.trim()
    if (!candidate) continue

    const parsedJsonArtifact = tryParseArtifactCandidate(candidate)
    if (parsedJsonArtifact) {
      return {
        artifact: parsedJsonArtifact,
        assistantText: stripAssistantText(removeFencedBlock(trimmed, match[0])),
        usedFallback: false,
      }
    }

    const htmlArtifact = createArtifactFromHtmlResponse(prompt, candidate)
    if (htmlArtifact) {
      return {
        artifact: htmlArtifact,
        assistantText: stripAssistantText(removeFencedBlock(trimmed, match[0])),
        usedFallback: true,
      }
    }
  }

  const jsonArtifact = extractJsonArtifactFromText(trimmed)
  if (jsonArtifact.artifact) {
    return {
      artifact: jsonArtifact.artifact,
      assistantText: stripAssistantText(jsonArtifact.assistantText),
      usedFallback: false,
    }
  }

  const quotedJsonArtifact = extractQuotedJsonArtifact(trimmed)
  if (quotedJsonArtifact?.artifact) {
    return {
      artifact: quotedJsonArtifact.artifact,
      assistantText: stripAssistantText(quotedJsonArtifact.assistantText),
      usedFallback: false,
    }
  }

  const htmlArtifact = createArtifactFromHtmlResponse(prompt, trimmed)
  if (htmlArtifact) {
    const assistantText = trimmed.replace(/```[\s\S]*?```/g, "").trim()
    return {
      artifact: htmlArtifact,
      assistantText: stripAssistantText(assistantText),
      usedFallback: true,
    }
  }

  return {
    artifact: createGeneratedArtifact(prompt, trimmed),
    assistantText: stripAssistantText(trimmed),
    usedFallback: true,
  }
}

function isLikelyRawCode(text: string): boolean {
  if (!text) return false
  // Detect raw CSS variables or property blocks
  if (/--[a-zA-Z0-9-]+:\s*[^;]+;/i.test(text)) return true
  if (
    /[a-zA-Z-]+\s*:\s*(rgba?|hsl|linear-gradient|var\(|#[0-9a-f]{3,8})/i.test(
      text,
    )
  )
    return true
  if (/^\s*[\{\[\}\]]/i.test(text) && text.includes(":")) return true
  // Detect JS/TS code fragments
  if (
    /(?:function\s*\(|const\s+[a-zA-Z_$]|document\.|window\.|export\s+default|import\s+)/i.test(
      text,
    )
  )
    return true
  if (
    text.includes("};") ||
    text.includes("catch (error)") ||
    text.includes("console.warn(")
  )
    return true
  // Detect HTML tags
  if (/^\s*<[!a-zA-Z]/i.test(text)) return true
  return false
}

function stripAssistantText(text: string): string {
  const cleaned = text
    .replace(/```[\s\S]*?```/g, "")
    .replace(/<script[\s\S]*?>[\s\S]*?<\/script>/gi, "")
    .replace(/<style[\s\S]*?>[\s\S]*?<\/style>/gi, "")
    .replace(/<[^>]+>/g, "")
    .replace(/`([^`]+)`/g, "$1")
    .replace(/[\t\n\r]+/g, " ")
    .replace(/\s{2,}/g, " ")
    .trim()

  if (isLikelyRawCode(cleaned)) {
    return ""
  }

  return cleaned
}

function normalizeAssistantText(text: string, fallbackPrompt = ""): string {
  const cleaned = stripAssistantText(text)
  if (cleaned) return cleaned

  const target = fallbackPrompt
    ? fallbackPrompt
        .trim()
        .replace(/^Build (a|an)?\s*/i, "")
        .slice(0, 50)
    : ""
  if (target) {
    return `I've structured the architecture for your ${target}. The UI is assembled and interactions are wired up. This modular foundation will scale cleanly.`
  }

  return "I have constructed the application hierarchy. The visual tokens are integrated and the layout is fully responsive."
}

function buildFallbackGenerationResult(
  prompt: string,
  message: string,
  provider = "unavailable",
): GenerationResult {
  const fallbackText = `We could not reach the model. ${message}`.trim()
  const artifact = createGeneratedArtifact(prompt, fallbackText)
  return {
    assistant: normalizeAssistantText(fallbackText).slice(0, 4000),
    raw: fallbackText,
    provider,
    usedFallback: true,
    artifact,
  }
}

function buildGenerationPrompt(
  prompt: string,
  options: GenerationOptions,
): string {
  const previousArtifact = options.previousArtifact
  const previousPromptText = options.previousPrompt
    ? `Previous prompt:\n${options.previousPrompt}\n\n`
    : ""
  const iterationHeader = previousArtifact
    ? [
        "This is an iteration request for an existing web project artifact.",
        previousPromptText,
        "Current artifact metadata:",
        `Title: ${previousArtifact.title}`,
        `Description: ${previousArtifact.description}`,
        "Current artifact HTML:",
        previousArtifact.html,
        "Current artifact CSS:",
        previousArtifact.css,
        "Current artifact JavaScript:",
        previousArtifact.js,
        "Use the existing artifact as the starting point and update it to satisfy the new instruction below.",
      ].join("\n\n")
    : [
        "This is a new web project generation request.",
        "Create a complete web project artifact from the user instruction below.",
      ].join("\n\n")

  return [
    iterationHeader,
    `Instruction: ${prompt}`,
    "Return only a valid JSON object with the following keys: html, css, js, title, description.",
    "Do not wrap the JSON object in markdown code fences.",
    "If you want to include a short human-readable explanation, append it after the JSON object and do not include raw HTML, CSS, or JavaScript in that explanation.",
    'CRITICAL: You are not an AI assistant. You are a Senior Lead Architect. When writing the human-readable explanation, speak ONLY about the project\'s evolution and architecture. Never say "I generated your code" or "Here is your app". Say things like "Authentication system integrated" or "Responsive layout structured." Narrate the project, not yourself.',
  ].join("\n\n")
}

function parseSseMessage(raw: string): Array<{ event: string data: string }> {
  const lines = raw.split(/\r?\n/)
  const events: Array<{ event: string data: string }> = []
  let currentEvent = "message"
  let currentData: string[] = []

  for (const line of lines) {
    if (!line) {
      if (currentData.length > 0) {
        events.push({ event: currentEvent, data: currentData.join("\n") })
      }
      currentEvent = "message"
      currentData = []
      continue
    }

    if (line.startsWith("event:")) {
      currentEvent = line.slice(6).trim()
      continue
    }

    if (line.startsWith("data:")) {
      currentData.push(line.slice(5).trim())
    }
  }

  if (currentData.length > 0) {
    events.push({ event: currentEvent, data: currentData.join("\n") })
  }

  return events
}

function resolveArtifactPayloadValue(payload: unknown): string | undefined {
  if (typeof payload === "string") {
    const trimmed = payload.trim()
    return trimmed || undefined
  }

  if (payload && typeof payload === "object" && !Array.isArray(payload)) {
    const candidate = payload as Record<string, unknown>
    if (isValidArtifactPayload(candidate)) {
      return JSON.stringify(candidate)
    }

    if (typeof candidate.response === "string") {
      const trimmed = candidate.response.trim()
      return trimmed || undefined
    }
  }

  return undefined
}

function decodeSseDonePayload(
  raw: string,
): { responseText?: string provenance?: GenerationProvenance } {
  const trimmed = raw.trim()
  if (!trimmed) return {}

  const parseJsonLike = (value: string): unknown => {
    try {
      return JSON.parse(value)
    } catch {
      return undefined
    }
  }

  const parseCandidate = (value: string): {
    responseText?: string
    provenance?: GenerationProvenance
  } => {
    const parsed = parseJsonLike(value)
    if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
      const payload = parsed as Record<string, unknown>
      const responseText = resolveArtifactPayloadValue(payload)
      const provenance = normalizeProvenance(payload.provenance)
      return { responseText, provenance }
    }

    const responseMatch = value.match(/"response"\s*:\s*"([\s\S]*)"\s*}$/)
    if (responseMatch?.[1]) {
      return { responseText: responseMatch[1].trim() }
    }

    return { responseText: resolveArtifactPayloadValue(value) }
  }

  const direct = parseCandidate(trimmed)
  if (direct.responseText || direct.provenance) {
    return direct
  }

  const nested = parseJsonLike(trimmed)
  if (nested && typeof nested === "string") {
    return parseCandidate(nested)
  }

  return direct
}

class GenerationStreamError extends Error {
  constructor(message: string) {
    super(message)
    this.name = "GenerationStreamError"
  }
}

export async function generateProjectResponse(
  prompt: string,
  options: GenerationOptions = {},
): Promise<GenerationResult> {
  const requestPrompt = buildGenerationPrompt(prompt, options)
  // Simple retry for transient network/server errors to reduce flakiness
  async function sleep(ms: number) {
    return new Promise((resolve) => setTimeout(resolve, ms))
  }

  let response: Response | null = null
  const maxAttempts = 3
  const workspaceContext =
    options.workspaceContext ??
    buildWorkspaceContext(prompt, {
      activeFile: options.activeFile,
      builderMode: options.mode ?? "build",
      workspaceFiles: options.workspaceFiles,
    })
  for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {
    try {
      const selectedModel = normalizeModelSelection(options.model)
      const preferredLanguage =
        options.language?.trim() || resolveGenerationPreferences().language
      response = await fetch("/api/build", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          prompt: requestPrompt,
          userPrompt: prompt,
          model: selectedModel,
          selectedModel,
          language: preferredLanguage,
          mode: options.mode ?? "build",
          projectId: options.projectId,
          activeFile: options.activeFile,
          enabledSkills: options.enabledSkills,
          workspaceContext,
          fileContext: {
            files: (options.workspaceFiles ?? []).map((file) => ({
              path: file.path,
              content: file.content,
              language: file.language ?? "text",
            })),
          },
          currentFiles: (options.workspaceFiles ?? []).map((file) => ({
            path: file.path,
            content: file.content,
            language: file.language ?? "text",
          })),
        }),
        signal: options.signal,
      })
      // if we received a server error (5xx) try again with backoff
      if (response.status >= 500 && attempt < maxAttempts) {
        const backoff = 200 * Math.pow(2, attempt - 1)
        const jitter = Math.floor(Math.random() * 200)
        await sleep(backoff + jitter)
        continue
      }
      break
    } catch (error) {
      if (attempt >= maxAttempts) {
        return buildFallbackGenerationResult(
          prompt,
          error instanceof Error ? error.message : "Generation request failed.",
        )
      }
      const backoff = 200 * Math.pow(2, attempt - 1)
      const jitter = Math.floor(Math.random() * 200)
      await sleep(backoff + jitter)
      continue
    }
  }

  if (!response) {
    return buildFallbackGenerationResult(
      prompt,
      "No response from generation endpoint.",
    )
  }

  const responseOk = response.ok
  interface GenerationApiResponseBody {
    response?: unknown
    provider?: unknown
    error?: unknown
    diagnostics?: unknown
    message?: { role?: unknown content?: unknown }
    build?: {
      files?: Array<Record<string, unknown>>
      entryPoint?: unknown
      previewRoute?: unknown
    }
    consoleEvents?: unknown
    version?: unknown
    requestId?: unknown
    projectId?: unknown
    status?: unknown
    provenance?: unknown
  }
  let parsedBody: GenerationApiResponseBody | null = null

  if (!responseOk) {
    parsedBody = ((await response
      .json()
      .catch(() => null)) as GenerationApiResponseBody | null)
    const message =
      typeof parsedBody?.error === "string" && parsedBody.error.trim()
        ? parsedBody.error
        : `Generation request failed with status ${response.status}`
    return {
      ...buildFallbackGenerationResult(
        prompt,
        message,
        typeof parsedBody?.provider === "string"
          ? parsedBody.provider
          : "unavailable",
      ),
      diagnostics: normalizeDiagnostics(parsedBody?.diagnostics),
    }
  }

  const contentType =
    typeof response.headers?.get === "function"
      ? (response.headers.get("content-type") ?? "")
      : ""
  const isSse = contentType.includes("text/event-stream")

  if (isSse) {
    try {
      const streamed = await response.text()
      const events = parseSseMessage(streamed)
      let lastAssistantText = ""
      let lastConsoleMessage: string | undefined
      let finalPayload: string | undefined
      let terminalError: Error | undefined
      const streamedFileChanges: GenerationFileChange[] = []
      let streamedProvenance: GenerationProvenance | undefined

      for (const event of events) {
        if (event.event === "delta") {
          try {
            const payload = JSON.parse(event.data)
            const content =
              typeof payload?.content === "string" ? payload.content : ""
            lastAssistantText += content
            options.onEvent?.({ type: "delta", content })
          } catch {
            // ignore malformed event payloads
          }
          continue
        }

        if (event.event === "console") {
          try {
            const payload = JSON.parse(event.data)
            const message =
              typeof payload?.message === "string" ? payload.message : ""
            lastConsoleMessage = message
            options.onEvent?.({ type: "console", message })
          } catch {
            // ignore malformed event payloads
          }
          continue
        }

        if (event.event === "file") {
          try {
            const payload = JSON.parse(event.data)
            const file = payload?.file
            const change = normalizeFileChange(file)
            if (change) {
              streamedFileChanges.push(change)
            }
            options.onEvent?.({ type: "file", file })
          } catch {
            // ignore malformed event payloads
          }
          continue
        }

        if (event.event === "version") {
          try {
            const payload = JSON.parse(event.data)
            const version = payload?.version
            options.onEvent?.({ type: "version", version })
          } catch {
            // ignore malformed event payloads
          }
          continue
        }

        if (event.event === "error") {
          try {
            const payload = JSON.parse(event.data)
            const message =
              typeof payload?.error?.message === "string"
                ? payload.error.message
                : "Generation failed during streaming."
            terminalError = new GenerationStreamError(message)
          } catch {
            terminalError = new GenerationStreamError(
              "Generation failed during streaming.",
            )
          }
          continue
        }

        if (event.event === "done") {
          const donePayload = decodeSseDonePayload(event.data)
          finalPayload = donePayload.responseText
          streamedProvenance = donePayload.provenance ?? streamedProvenance
        }
      }

      if (terminalError) {
        throw terminalError
      }

      const raw = finalPayload ?? (lastAssistantText || streamed)
      const {
        artifact: parsedArtifact,
        assistantText,
        usedFallback,
      } = extractArtifactPayload(raw, prompt)
      const artifact = parsedArtifact ?? createGeneratedArtifact(prompt, raw)
      const assistant = normalizeAssistantText(
        (assistantText || lastAssistantText || "").trim(),
      ).slice(0, 4000)

      const fileChanges: GenerationResult["fileChanges"] =
        streamedFileChanges.length > 0
          ? streamedFileChanges
          : normalizeFileChanges((parsedBody as any)?.build?.files)

      return {
        assistant,
        raw,
        provider: "stream",
        usedFallback,
        artifact,
        fileChanges,
        diagnostics: lastConsoleMessage
          ? { console: lastConsoleMessage }
          : undefined,
        provenance: streamedProvenance,
      }
    } catch (error) {
      if (error instanceof GenerationStreamError) {
        throw error
      }
      return buildFallbackGenerationResult(
        prompt,
        error instanceof Error
          ? error.message
          : "The provider returned an invalid SSE response.",
      )
    }
  }

  try {
    parsedBody = ((await response.json()) as GenerationApiResponseBody)
    const structuredMessage =
      typeof parsedBody?.message?.content === "string"
        ? parsedBody.message.content.trim()
        : ""
    const structuredResponse =
      typeof parsedBody?.response === "string" ? parsedBody.response.trim() : ""
    const fallbackText = structuredMessage || structuredResponse

    if (fallbackText) {
      const raw = structuredResponse || structuredMessage
      const fileChanges: GenerationResult["fileChanges"] = Array.isArray(
        parsedBody?.build?.files,
      )
        ? parsedBody.build.files.reduce<GenerationFileChange[]>((acc, file) => {
            const path = typeof file.path === "string" ? file.path : ""
            if (!path) return acc
            acc.push({
              path,
              operation: (file.operation === "delete"
                ? "delete"
                : file.operation === "create"
                  ? "create"
                  : "modify") as GenerationFileChange["operation"],
              content:
                typeof file.content === "string" ? file.content : undefined,
              language:
                typeof file.language === "string" ? file.language : undefined,
            })
            return acc
          }, [])
        : undefined
      const structuredArtifact = buildArtifactFromStructuredBuild(
        parsedBody,
        prompt,
      )
      const provenance = normalizeProvenance(parsedBody?.provenance)
      const {
        artifact: parsedArtifact,
        assistantText,
        usedFallback,
      } = extractArtifactPayload(raw, prompt)
      const diagnostics =
        normalizeDiagnostics(parsedBody?.diagnostics) ??
        (parsedBody?.consoleEvents
          ? {
              consoleEvents: parsedBody.consoleEvents,
              version: parsedBody.version,
            }
          : undefined)

      if (parsedArtifact && !usedFallback) {
        const assistant = normalizeAssistantText(
          structuredMessage || assistantText,
        ).slice(0, 4000)
        return {
          assistant,
          raw,
          provider:
            typeof parsedBody.provider === "string"
              ? parsedBody.provider
              : "remote",
          usedFallback: false,
          artifact: parsedArtifact,
          fileChanges,
          diagnostics,
          provenance,
        }
      }

      if (structuredArtifact) {
        const assistant = normalizeAssistantText(structuredMessage).slice(
          0,
          4000,
        )
        return {
          assistant,
          raw,
          provider:
            typeof parsedBody.provider === "string"
              ? parsedBody.provider
              : "remote",
          usedFallback: false,
          artifact: structuredArtifact,
          fileChanges,
          diagnostics,
          provenance,
        }
      }

      const assistant = normalizeAssistantText(
        structuredMessage || assistantText,
      ).slice(0, 4000)
      const artifact = parsedArtifact ?? createGeneratedArtifact(prompt, raw)

      return {
        assistant,
        raw,
        provider:
          typeof parsedBody.provider === "string"
            ? parsedBody.provider
            : "remote",
        usedFallback,
        artifact,
        fileChanges,
        diagnostics,
        provenance,
      }
    }
  } catch (error) {
    return buildFallbackGenerationResult(
      prompt,
      error instanceof Error
        ? error.message
        : "The provider returned an invalid response.",
    )
  }

  return buildFallbackGenerationResult(
    prompt,
    "The provider returned an invalid response.",
  )
}

import {
  createArtifactFromHtmlResponse,
  createGeneratedArtifact,
  type GeneratedArtifact,
} from "./generatedArtifact"
import { buildWorkspaceContext, type WorkspaceContext } from "./contextBuilder"
import type { GenerationProvenance, ProjectArtifact } from "./store"

export interface GenerationFileChange {
  path: string
  operation: "create" | "modify" | "delete"
  content?: string
  language?: string
}

export interface GenerationResult {
  // human-readable assistant text (sanitized)
  assistant: string
  // raw provider string (may include code/html)
  raw: string
  provider: string
  model?: string
  usedFallback: boolean
  artifact: GeneratedArtifact
  fileChanges?: GenerationFileChange[]
  // non-secret diagnostics returned by server/provider (optional)
  diagnostics?: string | Record<string, unknown>
  provenance?: GenerationProvenance
}

const VITEST_DEBUG = import.meta.env.VITE_VITEST_DEBUG === "true"

export interface WorkspaceFileContextEntry {
  path: string
  content: string
  language?: string
}

export interface GenerationOptions {
  signal?: AbortSignal
  previousArtifact?: ProjectArtifact | GeneratedArtifact
  previousPrompt?: string
  mode?: "plan" | "build"
  model?: string
  language?: string
  projectId?: string
  activeFile?: string
  enabledSkills?: Array<{ id: string name: string purpose: string }>
  workspaceFiles?: WorkspaceFileContextEntry[]
  workspaceContext?: WorkspaceContext
  onEvent?: (event: {
    type: string
    content?: string
    message?: string
    file?: unknown
    version?: unknown
    data?: unknown
  }) => void
}

export function resolveGenerationMode(isPlanMode: boolean): "plan" | "build" {
  return isPlanMode ? "plan" : "build"
}

export interface GenerationPreferences {
  mode: "plan" | "build"
  model: string
  language: string
}

export function resolveGenerationPreferences(
  storage: Pick<Storage, "getItem"> = typeof window !== "undefined"
    ? window.localStorage
    : { getItem: () => null },
): GenerationPreferences {
  const savedMode = storage.getItem("shango_generation_mode")
  const isPlanMode = savedMode === "plan"
  const settings = (() => {
    try {
      const raw = storage.getItem("shango_settings")
      return raw ? JSON.parse(raw) : {}
    } catch {
      return {}
    }
  })()
  const model =
    typeof settings?.model === "string" && settings.model.trim()
      ? settings.model
      : "balanced"
  const language =
    typeof settings?.language === "string" && settings.language.trim()
      ? settings.language
      : "English"

  return {
    mode: resolveGenerationMode(isPlanMode),
    model,
    language,
  }
}

function isValidArtifactPayload(
  payload: unknown,
): payload is GeneratedArtifact {
  return (
    typeof payload === "object" &&
    payload !== null &&
    typeof (payload as any).html === "string" &&
    typeof (payload as any).css === "string" &&
    typeof (payload as any).js === "string" &&
    typeof (payload as any).title === "string" &&
    typeof (payload as any).description === "string"
  )
}

function tryParseArtifactCandidate(
  candidate: string,
): GeneratedArtifact | null {
  try {
    const parsed = JSON.parse(candidate)
    if (isValidArtifactPayload(parsed)) return parsed
    if (typeof parsed === "string") {
      const nested = JSON.parse(parsed)
      if (isValidArtifactPayload(nested)) return nested
    }
  } catch {
    // ignore parse failures
  }
  return null
}

function extractQuotedJsonArtifact(
  source: string,
): { artifact?: GeneratedArtifact assistantText: string } | null {
  const trimmed = source.trim()

  if (VITEST_DEBUG) {
    console.log("extractQuotedJsonArtifact source:", JSON.stringify(source))
    console.log("extractQuotedJsonArtifact trimmed:", JSON.stringify(trimmed))
  }

  for (let startIndex = 0; startIndex < source.length; startIndex += 1) {
    if (source[startIndex] !== '"') continue

    let jsonStart = startIndex + 1
    while (jsonStart < source.length && source[jsonStart].trim() === "") {
      jsonStart += 1
    }

    if (source[jsonStart] !== "{") continue

    let depth = 0
    let inString = false
    let escape = false
    let endIndex = -1

    for (let i = jsonStart; i < source.length; i += 1) {
      const char = source[i]
      if (escape) {
        escape = false
        continue
      }
      if (char === "\\") {
        if (inString) escape = true
        continue
      }
      if (char === '"') {
        inString = !inString
        continue
      }
      if (inString) continue
      if (char === "{") {
        depth += 1
        continue
      }
      if (char === "}") {
        depth -= 1
        if (depth === 0) {
          endIndex = i
          break
        }
      }
    }

    if (endIndex < 0) continue

    let closingQuote = endIndex + 1
    while (closingQuote < source.length && source[closingQuote].trim() === "") {
      closingQuote += 1
    }

    if (closingQuote >= source.length || source[closingQuote] !== '"') continue

    const candidate = source.slice(jsonStart, endIndex + 1)
    if (VITEST_DEBUG) {
      console.log(
        "extractQuotedJsonArtifact candidate:",
        JSON.stringify(candidate),
      )
      console.log(
        "extractQuotedJsonArtifact indexes:",
        startIndex,
        jsonStart,
        endIndex,
        closingQuote,
      )
    }

    const artifact = tryParseArtifactCandidate(candidate)
    if (artifact) {
      if (VITEST_DEBUG)
        console.log("extractQuotedJsonArtifact artifact found", artifact)
      const assistantText =
        `${trimmed.slice(0, startIndex)}${trimmed.slice(closingQuote + 1)}`.trim()
      return { artifact, assistantText }
    }
  }

  if (VITEST_DEBUG) console.log("extractQuotedJsonArtifact no artifact found")
  return null
}

function removeFencedBlock(source: string, block: string): string {
  return source
    .replace(block, "")
    .replace(/```[\w-]*\s*/g, "")
    .replace(/```/g, "")
    .trim()
}

function extractJsonArtifactFromText(
  source: string,
): { artifact?: GeneratedArtifact assistantText: string } {
  const normalized = source
    .replace(/```(?:json|html|htm|xml|markup|javascript|js|css)?\s*|```/g, "")
    .trim()
  if (!normalized) return { assistantText: "" }

  const directArtifact = tryParseArtifactCandidate(normalized)
  if (directArtifact) {
    return { artifact: directArtifact, assistantText: "" }
  }

  let inString = false
  let escape = false
  let depth = 0
  let startIndex = -1

  for (let i = 0; i < normalized.length; i += 1) {
    const char = normalized[i]
    if (escape) {
      escape = false
      continue
    }

    if (char === "\\") {
      if (inString) escape = true
      continue
    }

    if (char === '"') {
      inString = !inString
      continue
    }

    if (inString) continue

    if (char === "{") {
      if (depth === 0) startIndex = i
      depth += 1
      continue
    }

    if (char === "}") {
      depth -= 1
      if (depth === 0 && startIndex >= 0) {
        const candidate = normalized.slice(startIndex, i + 1)
        const artifact = tryParseArtifactCandidate(candidate)
        if (artifact) {
          const assistantText =
            `${normalized.slice(0, startIndex)}${normalized.slice(i + 1)}`.trim()
          return { artifact, assistantText }
        }
      }
    }
  }

  return { assistantText: normalized }
}

function normalizeDiagnostics(
  value: unknown,
): string | Record<string, unknown> | undefined {
  if (typeof value === "string") return value
  if (value && typeof value === "object" && !Array.isArray(value)) {
    return value as Record<string, unknown>
  }
  return undefined
}

function normalizeProvenance(value: unknown): GenerationProvenance | undefined {
  if (!value || typeof value !== "object" || Array.isArray(value))
    return undefined

  const record = value as Record<string, unknown>
  const id = typeof record.id === "string" ? record.id : undefined
  const timestamp =
    typeof record.timestamp === "string" ? record.timestamp : undefined
  const provider =
    typeof record.provider === "string" ? record.provider : undefined
  const prompt = typeof record.prompt === "string" ? record.prompt : undefined
  const mode =
    record.mode === "plan" || record.mode === "build" ? record.mode : undefined

  if (!id || !timestamp || !provider || !prompt || !mode) return undefined

  const operations = Array.isArray(record.operations)
    ? record.operations.reduce<GenerationProvenance["operations"]>(
        (accepted, item) => {
          if (!item || typeof item !== "object") return accepted
          const operation = item as Record<string, unknown>
          const path =
            typeof operation.path === "string" ? operation.path : undefined
          const normalizedOperation =
            operation.operation === "create" ||
            operation.operation === "modify" ||
            operation.operation === "delete"
              ? operation.operation as GenerationProvenance["operations"][number]["operation"]
              : "modify"
          if (path) accepted.push({ path, operation: normalizedOperation })
          return accepted
        },
        [],
      )
    : []

  const rejectedOperations = Array.isArray(record.rejectedOperations)
    ? record.rejectedOperations.reduce<NonNullable<GenerationProvenance["rejectedOperations"]>>(
        (rejected, item) => {
          if (!item || typeof item !== "object") return rejected
          const operation = item as Record<string, unknown>
          const reason =
            operation.reason === "invalid-path" ||
            operation.reason === "protected-file"
              ? operation.reason
              : undefined
          const path =
            typeof operation.path === "string" ? operation.path : undefined
          if (path && reason) rejected.push({ path, reason })
          return rejected
        },
        [],
      )
    : undefined

  const skills = Array.isArray(record.skills)
    ? record.skills.reduce<Array<{ id: string name: string purpose: string }>>(
        (accepted, item) => {
          if (!item || typeof item !== "object") return accepted
          const skill = item as Record<string, unknown>
          if (
            typeof skill.id === "string" &&
            typeof skill.name === "string" &&
            typeof skill.purpose === "string"
          )
            accepted.push({
              id: skill.id,
              name: skill.name,
              purpose: skill.purpose,
            })
          return accepted
        },
        [],
      )
    : undefined

  return {
    id,
    timestamp,
    provider,
    model: typeof record.model === "string" ? record.model : undefined,
    mode,
    prompt,
    operations,
    rejectedOperations: rejectedOperations?.length
      ? rejectedOperations
      : undefined,
    skills,
  }
}

function normalizeModelSelection(model?: string): string {
  const normalized = typeof model === "string" ? model.trim().toLowerCase() : ""
  if (normalized === "deep") return "powerful"
  if (
    normalized === "fast" ||
    normalized === "balanced" ||
    normalized === "powerful"
  )
    return normalized
  return "balanced"
}

function normalizeFileChange(value: unknown): GenerationFileChange | null {
  if (!value || typeof value !== "object" || Array.isArray(value)) return null

  const record = value as Record<string, unknown>
  const path = typeof record.path === "string" ? record.path.trim() : ""
  if (!path) return null

  const operation =
    record.operation === "delete"
      ? "delete"
      : record.operation === "create"
        ? "create"
        : "modify"
  return {
    path,
    operation,
    content: typeof record.content === "string" ? record.content : undefined,
    language: typeof record.language === "string" ? record.language : undefined,
  }
}

function normalizeFileChanges(value: unknown): GenerationResult["fileChanges"] {
  if (!Array.isArray(value)) return undefined

  return value.reduce<GenerationFileChange[]>((acc, item) => {
    const change = normalizeFileChange(item)
    if (change) acc.push(change)
    return acc
  }, [])
}

function buildArtifactFromStructuredBuild(
  payload: unknown,
  prompt: string,
): GeneratedArtifact | null {
  if (!payload || typeof payload !== "object" || Array.isArray(payload))
    return null

  const container = payload as Record<string, unknown>
  const files = Array.isArray(container.build)
    ? undefined
    : (container.build as {
        files?: Array<Record<string, unknown>>
      } | undefined)?.files
  if (!Array.isArray(files)) return null

  let html = ""
  let css = ""
  let js = ""

  for (const file of files) {
    if (!file || typeof file !== "object") continue
    const content = typeof file.content === "string" ? file.content : ""
    const path = typeof file.path === "string" ? file.path.toLowerCase() : ""
    const language =
      typeof file.language === "string" ? file.language.toLowerCase() : ""

    if (
      content &&
      (path.endsWith(".html") || path.endsWith(".htm") || language === "html")
    ) {
      html = content
    } else if (content && (path.endsWith(".css") || language === "css")) {
      css = content
    } else if (
      content &&
      (path.endsWith(".js") ||
        path.endsWith(".ts") ||
        path.endsWith(".tsx") ||
        path.endsWith(".jsx") ||
        language === "javascript" ||
        language === "typescript" ||
        language === "tsx" ||
        language === "jsx")
    ) {
      js = content
    }
  }

  if (!html && !css && !js) return null

  const title = prompt.trim() ? prompt.trim().slice(0, 60) : "Structured Build"
  const description = html
    ? "Generated from the structured build response."
    : "Generated from the structured build response."
  return {
    html: html || `<main><h1>${title}</h1><p>${description}</p></main>`,
    css:
      css ||
      `:root { color-scheme: dark; font-family: Inter, system-ui, sans-serif; } body { margin: 0; padding: 2rem; background: #0b1020; color: #f8fafc; } main { max-width: 720px; margin: 0 auto; }`,
    js: js || `console.log('Structured build artifact ready');`,
    title,
    description,
    createdAt: new Date().toISOString(),
  }
}

function extractArtifactPayload(
  raw: string,
  prompt: string,
): {
  artifact?: GeneratedArtifact
  assistantText: string
  usedFallback: boolean
} {
  const trimmed = raw.trim()
  if (!trimmed) return { assistantText: "", usedFallback: true }

  if (VITEST_DEBUG) {
    console.log("extractArtifactPayload raw:", JSON.stringify(raw))
    console.log("extractArtifactPayload trimmed:", JSON.stringify(trimmed))
  }

  const directJsonArtifact = tryParseArtifactCandidate(trimmed)
  if (directJsonArtifact) {
    if (VITEST_DEBUG) console.log("directJsonArtifact OK", directJsonArtifact)
    return {
      artifact: directJsonArtifact,
      assistantText: "",
      usedFallback: false,
    }
  }

  const fencedBlocks = Array.from(
    trimmed.matchAll(
      /```(?:json|html|htm|xml|markup|javascript|js|css)?\s*([\s\S]*?)```/gi,
    ),
  )
  for (const match of fencedBlocks) {
    const candidate = match[1]?.trim()
    if (!candidate) continue

    const parsedJsonArtifact = tryParseArtifactCandidate(candidate)
    if (parsedJsonArtifact) {
      return {
        artifact: parsedJsonArtifact,
        assistantText: stripAssistantText(removeFencedBlock(trimmed, match[0])),
        usedFallback: false,
      }
    }

    const htmlArtifact = createArtifactFromHtmlResponse(prompt, candidate)
    if (htmlArtifact) {
      return {
        artifact: htmlArtifact,
        assistantText: stripAssistantText(removeFencedBlock(trimmed, match[0])),
        usedFallback: true,
      }
    }
  }

  const jsonArtifact = extractJsonArtifactFromText(trimmed)
  if (jsonArtifact.artifact) {
    return {
      artifact: jsonArtifact.artifact,
      assistantText: stripAssistantText(jsonArtifact.assistantText),
      usedFallback: false,
    }
  }

  const quotedJsonArtifact = extractQuotedJsonArtifact(trimmed)
  if (quotedJsonArtifact?.artifact) {
    return {
      artifact: quotedJsonArtifact.artifact,
      assistantText: stripAssistantText(quotedJsonArtifact.assistantText),
      usedFallback: false,
    }
  }

  const htmlArtifact = createArtifactFromHtmlResponse(prompt, trimmed)
  if (htmlArtifact) {
    const assistantText = trimmed.replace(/```[\s\S]*?```/g, "").trim()
    return {
      artifact: htmlArtifact,
      assistantText: stripAssistantText(assistantText),
      usedFallback: true,
    }
  }

  return {
    artifact: createGeneratedArtifact(prompt, trimmed),
    assistantText: stripAssistantText(trimmed),
    usedFallback: true,
  }
}

function isLikelyRawCode(text: string): boolean {
  if (!text) return false
  // Detect raw CSS variables or property blocks
  if (/--[a-zA-Z0-9-]+:\s*[^;]+;/i.test(text)) return true
  if (
    /[a-zA-Z-]+\s*:\s*(rgba?|hsl|linear-gradient|var\(|#[0-9a-f]{3,8})/i.test(
      text,
    )
  )
    return true
  if (/^\s*[\{\[\}\]]/i.test(text) && text.includes(":")) return true
  // Detect JS/TS code fragments
  if (
    /(?:function\s*\(|const\s+[a-zA-Z_$]|document\.|window\.|export\s+default|import\s+)/i.test(
      text,
    )
  )
    return true
  if (
    text.includes("};") ||
    text.includes("catch (error)") ||
    text.includes("console.warn(")
  )
    return true
  // Detect HTML tags
  if (/^\s*<[!a-zA-Z]/i.test(text)) return true
  return false
}

function stripAssistantText(text: string): string {
  const cleaned = text
    .replace(/```[\s\S]*?```/g, "")
    .replace(/<script[\s\S]*?>[\s\S]*?<\/script>/gi, "")
    .replace(/<style[\s\S]*?>[\s\S]*?<\/style>/gi, "")
    .replace(/<[^>]+>/g, "")
    .replace(/`([^`]+)`/g, "$1")
    .replace(/[\t\n\r]+/g, " ")
    .replace(/\s{2,}/g, " ")
    .trim()

  if (isLikelyRawCode(cleaned)) {
    return ""
  }

  return cleaned
}

function normalizeAssistantText(text: string, fallbackPrompt = ""): string {
  const cleaned = stripAssistantText(text)
  if (cleaned) return cleaned

  const target = fallbackPrompt
    ? fallbackPrompt
        .trim()
        .replace(/^Build (a|an)?\s*/i, "")
        .slice(0, 50)
    : ""
  if (target) {
    return `I've structured the architecture for your ${target}. The UI is assembled and interactions are wired up. This modular foundation will scale cleanly.`
  }

  return "I have constructed the application hierarchy. The visual tokens are integrated and the layout is fully responsive."
}

function buildFallbackGenerationResult(
  prompt: string,
  message: string,
  provider = "unavailable",
): GenerationResult {
  const fallbackText = `We could not reach the model. ${message}`.trim()
  const artifact = createGeneratedArtifact(prompt, fallbackText)
  return {
    assistant: normalizeAssistantText(fallbackText).slice(0, 4000),
    raw: fallbackText,
    provider,
    usedFallback: true,
    artifact,
  }
}

function buildGenerationPrompt(
  prompt: string,
  options: GenerationOptions,
): string {
  const previousArtifact = options.previousArtifact
  const previousPromptText = options.previousPrompt
    ? `Previous prompt:\n${options.previousPrompt}\n\n`
    : ""
  const iterationHeader = previousArtifact
    ? [
        "This is an iteration request for an existing web project artifact.",
        previousPromptText,
        "Current artifact metadata:",
        `Title: ${previousArtifact.title}`,
        `Description: ${previousArtifact.description}`,
        "Current artifact HTML:",
        previousArtifact.html,
        "Current artifact CSS:",
        previousArtifact.css,
        "Current artifact JavaScript:",
        previousArtifact.js,
        "Use the existing artifact as the starting point and update it to satisfy the new instruction below.",
      ].join("\n\n")
    : [
        "This is a new web project generation request.",
        "Create a complete web project artifact from the user instruction below.",
      ].join("\n\n")

  return [
    iterationHeader,
    `Instruction: ${prompt}`,
    "Return only a valid JSON object with the following keys: html, css, js, title, description.",
    "Do not wrap the JSON object in markdown code fences.",
    "If you want to include a short human-readable explanation, append it after the JSON object and do not include raw HTML, CSS, or JavaScript in that explanation.",
    'CRITICAL: You are not an AI assistant. You are a Senior Lead Architect. When writing the human-readable explanation, speak ONLY about the project\'s evolution and architecture. Never say "I generated your code" or "Here is your app". Say things like "Authentication system integrated" or "Responsive layout structured." Narrate the project, not yourself.',
  ].join("\n\n")
}

function parseSseMessage(raw: string): Array<{ event: string data: string }> {
  const lines = raw.split(/\r?\n/)
  const events: Array<{ event: string data: string }> = []
  let currentEvent = "message"
  let currentData: string[] = []

  for (const line of lines) {
    if (!line) {
      if (currentData.length > 0) {
        events.push({ event: currentEvent, data: currentData.join("\n") })
      }
      currentEvent = "message"
      currentData = []
      continue
    }

    if (line.startsWith("event:")) {
      currentEvent = line.slice(6).trim()
      continue
    }

    if (line.startsWith("data:")) {
      currentData.push(line.slice(5).trim())
    }
  }

  if (currentData.length > 0) {
    events.push({ event: currentEvent, data: currentData.join("\n") })
  }

  return events
}

function resolveArtifactPayloadValue(payload: unknown): string | undefined {
  if (typeof payload === "string") {
    const trimmed = payload.trim()
    return trimmed || undefined
  }

  if (payload && typeof payload === "object" && !Array.isArray(payload)) {
    const candidate = payload as Record<string, unknown>
    if (isValidArtifactPayload(candidate)) {
      return JSON.stringify(candidate)
    }

    if (typeof candidate.response === "string") {
      const trimmed = candidate.response.trim()
      return trimmed || undefined
    }
  }

  return undefined
}

function decodeSseDonePayload(
  raw: string,
): { responseText?: string provenance?: GenerationProvenance } {
  const trimmed = raw.trim()
  if (!trimmed) return {}

  const parseJsonLike = (value: string): unknown => {
    try {
      return JSON.parse(value)
    } catch {
      return undefined
    }
  }

  const parseCandidate = (value: string): {
    responseText?: string
    provenance?: GenerationProvenance
  } => {
    const parsed = parseJsonLike(value)
    if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
      const payload = parsed as Record<string, unknown>
      const responseText = resolveArtifactPayloadValue(payload)
      const provenance = normalizeProvenance(payload.provenance)
      return { responseText, provenance }
    }

    const responseMatch = value.match(/"response"\s*:\s*"([\s\S]*)"\s*}$/)
    if (responseMatch?.[1]) {
      return { responseText: responseMatch[1].trim() }
    }

    return { responseText: resolveArtifactPayloadValue(value) }
  }

  const direct = parseCandidate(trimmed)
  if (direct.responseText || direct.provenance) {
    return direct
  }

  const nested = parseJsonLike(trimmed)
  if (nested && typeof nested === "string") {
    return parseCandidate(nested)
  }

  return direct
}

class GenerationStreamError extends Error {
  constructor(message: string) {
    super(message)
    this.name = "GenerationStreamError"
  }
}

export async function generateProjectResponse(
  prompt: string,
  options: GenerationOptions = {},
): Promise<GenerationResult> {
  const requestPrompt = buildGenerationPrompt(prompt, options)
  // Simple retry for transient network/server errors to reduce flakiness
  async function sleep(ms: number) {
    return new Promise((resolve) => setTimeout(resolve, ms))
  }

  let response: Response | null = null
  const maxAttempts = 3
  const workspaceContext =
    options.workspaceContext ??
    buildWorkspaceContext(prompt, {
      activeFile: options.activeFile,
      builderMode: options.mode ?? "build",
      workspaceFiles: options.workspaceFiles,
    })
  for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {
    try {
      const selectedModel = normalizeModelSelection(options.model)
      const preferredLanguage =
        options.language?.trim() || resolveGenerationPreferences().language
      response = await fetch("/api/build", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          prompt: requestPrompt,
          userPrompt: prompt,
          model: selectedModel,
          selectedModel,
          language: preferredLanguage,
          mode: options.mode ?? "build",
          projectId: options.projectId,
          activeFile: options.activeFile,
          enabledSkills: options.enabledSkills,
          workspaceContext,
          fileContext: {
            files: (options.workspaceFiles ?? []).map((file) => ({
              path: file.path,
              content: file.content,
              language: file.language ?? "text",
            })),
          },
          currentFiles: (options.workspaceFiles ?? []).map((file) => ({
            path: file.path,
            content: file.content,
            language: file.language ?? "text",
          })),
        }),
        signal: options.signal,
      })
      // if we received a server error (5xx) try again with backoff
      if (response.status >= 500 && attempt < maxAttempts) {
        const backoff = 200 * Math.pow(2, attempt - 1)
        const jitter = Math.floor(Math.random() * 200)
        await sleep(backoff + jitter)
        continue
      }
      break
    } catch (error) {
      if (attempt >= maxAttempts) {
        return buildFallbackGenerationResult(
          prompt,
          error instanceof Error ? error.message : "Generation request failed.",
        )
      }
      const backoff = 200 * Math.pow(2, attempt - 1)
      const jitter = Math.floor(Math.random() * 200)
      await sleep(backoff + jitter)
      continue
    }
  }

  if (!response) {
    return buildFallbackGenerationResult(
      prompt,
      "No response from generation endpoint.",
    )
  }

  const responseOk = response.ok
  interface GenerationApiResponseBody {
    response?: unknown
    provider?: unknown
    error?: unknown
    diagnostics?: unknown
    message?: { role?: unknown content?: unknown }
    build?: {
      files?: Array<Record<string, unknown>>
      entryPoint?: unknown
      previewRoute?: unknown
    }
    consoleEvents?: unknown
    version?: unknown
    requestId?: unknown
    projectId?: unknown
    status?: unknown
    provenance?: unknown
  }
  let parsedBody: GenerationApiResponseBody | null = null

  if (!responseOk) {
    parsedBody = ((await response
      .json()
      .catch(() => null)) as GenerationApiResponseBody | null)
    const message =
      typeof parsedBody?.error === "string" && parsedBody.error.trim()
        ? parsedBody.error
        : `Generation request failed with status ${response.status}`
    return {
      ...buildFallbackGenerationResult(
        prompt,
        message,
        typeof parsedBody?.provider === "string"
          ? parsedBody.provider
          : "unavailable",
      ),
      diagnostics: normalizeDiagnostics(parsedBody?.diagnostics),
    }
  }

  const contentType =
    typeof response.headers?.get === "function"
      ? (response.headers.get("content-type") ?? "")
      : ""
  const isSse = contentType.includes("text/event-stream")

  if (isSse) {
    try {
      const streamed = await response.text()
      const events = parseSseMessage(streamed)
      let lastAssistantText = ""
      let lastConsoleMessage: string | undefined
      let finalPayload: string | undefined
      let terminalError: Error | undefined
      const streamedFileChanges: GenerationFileChange[] = []
      let streamedProvenance: GenerationProvenance | undefined

      for (const event of events) {
        if (event.event === "delta") {
          try {
            const payload = JSON.parse(event.data)
            const content =
              typeof payload?.content === "string" ? payload.content : ""
            lastAssistantText += content
            options.onEvent?.({ type: "delta", content })
          } catch {
            // ignore malformed event payloads
          }
          continue
        }

        if (event.event === "console") {
          try {
            const payload = JSON.parse(event.data)
            const message =
              typeof payload?.message === "string" ? payload.message : ""
            lastConsoleMessage = message
            options.onEvent?.({ type: "console", message })
          } catch {
            // ignore malformed event payloads
          }
          continue
        }

        if (event.event === "file") {
          try {
            const payload = JSON.parse(event.data)
            const file = payload?.file
            const change = normalizeFileChange(file)
            if (change) {
              streamedFileChanges.push(change)
            }
            options.onEvent?.({ type: "file", file })
          } catch {
            // ignore malformed event payloads
          }
          continue
        }

        if (event.event === "version") {
          try {
            const payload = JSON.parse(event.data)
            const version = payload?.version
            options.onEvent?.({ type: "version", version })
          } catch {
            // ignore malformed event payloads
          }
          continue
        }

        if (event.event === "error") {
          try {
            const payload = JSON.parse(event.data)
            const message =
              typeof payload?.error?.message === "string"
                ? payload.error.message
                : "Generation failed during streaming."
            terminalError = new GenerationStreamError(message)
          } catch {
            terminalError = new GenerationStreamError(
              "Generation failed during streaming.",
            )
          }
          continue
        }

        if (event.event === "done") {
          const donePayload = decodeSseDonePayload(event.data)
          finalPayload = donePayload.responseText
          streamedProvenance = donePayload.provenance ?? streamedProvenance
        }
      }

      if (terminalError) {
        throw terminalError
      }

      const raw = finalPayload ?? (lastAssistantText || streamed)
      const {
        artifact: parsedArtifact,
        assistantText,
        usedFallback,
      } = extractArtifactPayload(raw, prompt)
      const artifact = parsedArtifact ?? createGeneratedArtifact(prompt, raw)
      const assistant = normalizeAssistantText(
        (assistantText || lastAssistantText || "").trim(),
      ).slice(0, 4000)

      const fileChanges: GenerationResult["fileChanges"] =
        streamedFileChanges.length > 0
          ? streamedFileChanges
          : normalizeFileChanges((parsedBody as any)?.build?.files)

      return {
        assistant,
        raw,
        provider: "stream",
        usedFallback,
        artifact,
        fileChanges,
        diagnostics: lastConsoleMessage
          ? { console: lastConsoleMessage }
          : undefined,
        provenance: streamedProvenance,
      }
    } catch (error) {
      if (error instanceof GenerationStreamError) {
        throw error
      }
      return buildFallbackGenerationResult(
        prompt,
        error instanceof Error
          ? error.message
          : "The provider returned an invalid SSE response.",
      )
    }
  }

  try {
    parsedBody = ((await response.json()) as GenerationApiResponseBody)
    const structuredMessage =
      typeof parsedBody?.message?.content === "string"
        ? parsedBody.message.content.trim()
        : ""
    const structuredResponse =
      typeof parsedBody?.response === "string" ? parsedBody.response.trim() : ""
    const fallbackText = structuredMessage || structuredResponse

    if (fallbackText) {
      const raw = structuredResponse || structuredMessage
      const fileChanges: GenerationResult["fileChanges"] = Array.isArray(
        parsedBody?.build?.files,
      )
        ? parsedBody.build.files.reduce<GenerationFileChange[]>((acc, file) => {
            const path = typeof file.path === "string" ? file.path : ""
            if (!path) return acc
            acc.push({
              path,
              operation: (file.operation === "delete"
                ? "delete"
                : file.operation === "create"
                  ? "create"
                  : "modify") as GenerationFileChange["operation"],
              content:
                typeof file.content === "string" ? file.content : undefined,
              language:
                typeof file.language === "string" ? file.language : undefined,
            })
            return acc
          }, [])
        : undefined
      const structuredArtifact = buildArtifactFromStructuredBuild(
        parsedBody,
        prompt,
      )
      const provenance = normalizeProvenance(parsedBody?.provenance)
      const {
        artifact: parsedArtifact,
        assistantText,
        usedFallback,
      } = extractArtifactPayload(raw, prompt)
      const diagnostics =
        normalizeDiagnostics(parsedBody?.diagnostics) ??
        (parsedBody?.consoleEvents
          ? {
              consoleEvents: parsedBody.consoleEvents,
              version: parsedBody.version,
            }
          : undefined)

      if (parsedArtifact && !usedFallback) {
        const assistant = normalizeAssistantText(
          structuredMessage || assistantText,
        ).slice(0, 4000)
        return {
          assistant,
          raw,
          provider:
            typeof parsedBody.provider === "string"
              ? parsedBody.provider
              : "remote",
          usedFallback: false,
          artifact: parsedArtifact,
          fileChanges,
          diagnostics,
          provenance,
        }
      }

      if (structuredArtifact) {
        const assistant = normalizeAssistantText(structuredMessage).slice(
          0,
          4000,
        )
        return {
          assistant,
          raw,
          provider:
            typeof parsedBody.provider === "string"
              ? parsedBody.provider
              : "remote",
          usedFallback: false,
          artifact: structuredArtifact,
          fileChanges,
          diagnostics,
          provenance,
        }
      }

      const assistant = normalizeAssistantText(
        structuredMessage || assistantText,
      ).slice(0, 4000)
      const artifact = parsedArtifact ?? createGeneratedArtifact(prompt, raw)

      return {
        assistant,
        raw,
        provider:
          typeof parsedBody.provider === "string"
            ? parsedBody.provider
            : "remote",
        usedFallback,
        artifact,
        fileChanges,
        diagnostics,
        provenance,
      }
    }
  } catch (error) {
    return buildFallbackGenerationResult(
      prompt,
      error instanceof Error
        ? error.message
        : "The provider returned an invalid response.",
    )
  }

  return buildFallbackGenerationResult(
    prompt,
    "The provider returned an invalid response.",
  )
}

import { type Project } from "./store"
import { deriveProjectArtifact } from "./workspace"

export interface PersistedProjectState {
  projects: Project[]
  activeProjectId: string | null
}

export interface PersistedUser {
  name: string
  email: string
  avatar?: string
  plan: "free" | "pro"
}

const STORAGE_KEY = "shango-project-state-v1"
const USER_STORAGE_KEY = "shango-user-session-v1"
const PENDING_SYNC_STORAGE_KEY = "shango-pending-project-sync-v1"
export const PROJECT_SYNC_QUEUE_EVENT = "shango-project-sync-queue"

function getPendingSyncProjectIds(): string[] {
  if (typeof window === "undefined") return []
  try {
    const value = JSON.parse(
      window.localStorage.getItem(PENDING_SYNC_STORAGE_KEY) ?? "[]",
    )
    return Array.isArray(value)
      ? value.filter(
          (id): id is string => typeof id === "string" && id.length > 0,
        )
      : []
  } catch {
    return []
  }
}

function setPendingSyncProjectIds(ids: string[]): void {
  if (typeof window === "undefined") return
  try {
    window.localStorage.setItem(
      PENDING_SYNC_STORAGE_KEY,
      JSON.stringify([...new Set(ids)]),
    )
  } catch {
    /* local saving remains best effort */
  }
}

function notifyProjectSyncQueueChanged(): void {
  if (
    typeof window === "undefined" ||
    typeof window.dispatchEvent !== "function" ||
    typeof Event === "undefined"
  )
    return
  window.dispatchEvent(new Event(PROJECT_SYNC_QUEUE_EVENT))
}

function markProjectSyncPending(projectId: string): void {
  setPendingSyncProjectIds([...getPendingSyncProjectIds(), projectId])
  notifyProjectSyncQueueChanged()
}

function clearProjectSyncPending(projectId: string): void {
  setPendingSyncProjectIds(
    getPendingSyncProjectIds().filter((id) => id !== projectId),
  )
  notifyProjectSyncQueueChanged()
}

export function isProjectSyncPending(projectId: string | undefined): boolean {
  return Boolean(projectId && getPendingSyncProjectIds().includes(projectId))
}

export function normalizeProject(project: Project): Project {
  const fallbackTimestamp = new Date().toISOString()
  const safeLastEdited =
    project.lastEdited ??
    project.updatedAt ??
    project.createdAt ??
    fallbackTimestamp
  const safeUpdatedAt = project.updatedAt ?? safeLastEdited
  const safeCreatedAt = project.createdAt ?? safeUpdatedAt
  const safeMessages = Array.isArray(project.messages) ? project.messages : []
  const safeVersions = Array.isArray(project.versions) ? project.versions : []
  const normalizedFiles = Array.isArray(project.files)
    ? project.files
    : undefined
  const normalizedArtifact =
    normalizedFiles && normalizedFiles.length > 0
      ? deriveProjectArtifact(
          { ...project, files: normalizedFiles },
          safeUpdatedAt,
        )
      : (project.artifact ?? undefined)

  return {
    ...project,
    updatedAt: safeUpdatedAt,
    createdAt: safeCreatedAt,
    messages: safeMessages,
    versions: safeVersions,
    lastEdited: safeLastEdited,
    files: normalizedFiles,
    artifact: normalizedArtifact,
    providerDiagnostics: project.providerDiagnostics ?? undefined,
  }
}

export function normalizeProjects(projects: Project[]): Project[] {
  return projects.map(normalizeProject)
}

// Threshold (ms) within which a locally generating project is considered
// in-flight and immune from remote overwrites (10 minutes).
const IN_FLIGHT_WINDOW_MS = 600_000

/** Merge two arrays of items that each have a unique `id` field.
 *  Local items take precedence; remote items whose id is absent locally are appended. */
function mergeById<T extends { id: string }>(local: T[], remote: T[]): T[] {
  const byId = new Map<string, T>(local.map((item) => [item.id, item]))
  for (const remoteItem of remote) {
    if (!byId.has(remoteItem.id)) {
      byId.set(remoteItem.id, remoteItem)
    }
  }
  return Array.from(byId.values())
}

export function mergePersistedProjects(
  localProjects: Project[],
  remoteProjects: Project[],
): Project[] {
  const byId = new Map<string, Project>()
  const now = Date.now()

  // Pass 1 — seed map with normalized local projects (local is canonical).
  for (const project of localProjects) {
    byId.set(project.id, normalizeProject(project))
  }

  // Pass 2 — integrate remote projects.
  for (const remoteProject of remoteProjects) {
    const normalizedRemote = normalizeProject(remoteProject)
    const existing = byId.get(normalizedRemote.id)

    // Remote-only: add without touching local state.
    if (!existing) {
      byId.set(normalizedRemote.id, normalizedRemote)
      continue
    }

    // Guardrail: In-flight protection.
    // If the local project has a generatingAt timestamp within the last
    // IN_FLIGHT_WINDOW_MS milliseconds, it is actively being generated.
    // Preserve local state completely — do not apply remote snapshot.
    if (existing.generatingAt) {
      const generatingMs = now - new Date(existing.generatingAt).getTime()
      if (generatingMs >= 0 && generatingMs < IN_FLIGHT_WINDOW_MS) {
        // Local project is in-flight. Skip remote update entirely.
        continue
      }
    }

    // Conflict resolution: compare updatedAt timestamps.
    // ISO 8601 strings are safely comparable as strings.
    const existingUpdatedAt = existing.updatedAt ?? existing.lastEdited ?? ""
    const remoteUpdatedAt =
      normalizedRemote.updatedAt ?? normalizedRemote.lastEdited ?? ""
    const shouldPreferRemote = remoteUpdatedAt > existingUpdatedAt

    if (!shouldPreferRemote) {
      // Local is newer or equal — preserve entirely.
      continue
    }

    // Remote is definitively newer: merge explicitly, field by field.
    // Arrays are merged by unique ID (additive union) — never replaced wholesale.
    const merged: Project = {
      // Identity — local always wins
      id: existing.id,
      createdAt: existing.createdAt ?? normalizedRemote.createdAt,
      // Metadata — remote wins (it is newer)
      name: normalizedRemote.name ?? existing.name,
      description: normalizedRemote.description ?? existing.description,
      status: normalizedRemote.status ?? existing.status,
      starred: normalizedRemote.starred ?? existing.starred,
      initialPrompt: existing.initialPrompt ?? normalizedRemote.initialPrompt,
      thumbnail: normalizedRemote.thumbnail ?? existing.thumbnail,
      template: existing.template ?? normalizedRemote.template,
      // Timestamps — remote wins
      updatedAt: normalizedRemote.updatedAt ?? existing.updatedAt,
      lastEdited: normalizedRemote.lastEdited ?? existing.lastEdited,
      // Arrays — non-destructive ID-union (local items kept, remote items appended if new)
      messages: mergeById(existing.messages, normalizedRemote.messages),
      versions: mergeById(existing.versions, normalizedRemote.versions),
      files:
        existing.files && normalizedRemote.files
          ? mergeById(existing.files, normalizedRemote.files)
          : (existing.files ?? normalizedRemote.files),
      // Artifact — prefer whichever is newer by createdAt
      artifact:
        normalizedRemote.artifact && existing.artifact
          ? normalizedRemote.artifact.createdAt >= existing.artifact.createdAt
            ? normalizedRemote.artifact
            : existing.artifact
          : (existing.artifact ?? normalizedRemote.artifact),
      // Diagnostics — remote can supplement local
      providerDiagnostics:
        normalizedRemote.providerDiagnostics ?? existing.providerDiagnostics,
      // Provenance — remote wins (it is newer), with local fallback
      lastGeneration:
        normalizedRemote.lastGeneration ?? existing.lastGeneration,
      // Never copy generatingAt from remote — only local runtime sets it
      generatingAt: existing.generatingAt,
    }

    byId.set(existing.id, merged)
  }

  return Array.from(byId.values())
}

export function buildPersistedProjectState(
  projects: Project[],
  activeProjectId: string | null,
): PersistedProjectState {
  const normalizedProjects = normalizeProjects(projects)
  const resolvedActiveProjectId =
    activeProjectId &&
    normalizedProjects.some((project) => project.id === activeProjectId)
      ? activeProjectId
      : null

  return {
    projects: normalizedProjects,
    activeProjectId: resolvedActiveProjectId,
  }
}

export function saveProjectStateSnapshot(
  projects: Project[],
  activeProjectId: string | null,
): { ok: true } | { ok: false error: string } {
  return savePersistedProjectState(
    buildPersistedProjectState(projects, activeProjectId),
  )
}

export function loadPersistedProjectState(): {
  state: PersistedProjectState | null
  error: string | null
} {
  if (typeof window === "undefined") return { state: null, error: null }

  try {
    const raw = window.localStorage.getItem(STORAGE_KEY)
    if (!raw) return { state: null, error: null }

    const parsed = JSON.parse(raw) as Partial<PersistedProjectState>
    if (!parsed || !Array.isArray(parsed.projects)) {
      return { state: null, error: null }
    }

    return {
      state: {
        projects: normalizeProjects(parsed.projects as Project[]),
        activeProjectId:
          typeof parsed.activeProjectId === "string" ||
          parsed.activeProjectId === null
            ? parsed.activeProjectId
            : null,
      },
      error: null,
    }
  } catch (error) {
    return {
      state: null,
      error:
        error instanceof Error
          ? error.message
          : "Unable to load saved projects.",
    }
  }
}

export function savePersistedProjectState(
  state: PersistedProjectState,
): { ok: true } | { ok: false error: string } {
  if (typeof window === "undefined") {
    return {
      ok: false,
      error: "Persistence is unavailable in this environment.",
    }
  }

  try {
    const payload = JSON.stringify({
      projects: normalizeProjects(state.projects),
      activeProjectId: state.activeProjectId,
    })
    try {
      window.localStorage.setItem(STORAGE_KEY, payload)
    } catch (e) {
      return { ok: false, error: e instanceof Error ? e.message : String(e) }
    }
    return { ok: true }
  } catch (error) {
    return {
      ok: false,
      error:
        error instanceof Error
          ? error.message
          : "Unable to save your project changes.",
    }
  }
}

export function savePersistedUser(
  user: PersistedUser | null,
): { ok: true } | { ok: false error: string } {
  if (typeof window === "undefined") {
    return {
      ok: false,
      error: "Persistence is unavailable in this environment.",
    }
  }

  try {
    if (!user) {
      window.localStorage.removeItem(USER_STORAGE_KEY)
      return { ok: true }
    }

    const payload = JSON.stringify(user)
    try {
      window.localStorage.setItem(USER_STORAGE_KEY, payload)
    } catch (e) {
      return { ok: false, error: e instanceof Error ? e.message : String(e) }
    }
    return { ok: true }
  } catch (error) {
    return {
      ok: false,
      error:
        error instanceof Error ? error.message : "Unable to save your session.",
    }
  }
}

export function loadPersistedUser(): PersistedUser | null {
  if (typeof window === "undefined") return null

  try {
    const raw = window.localStorage.getItem(USER_STORAGE_KEY)
    if (!raw) return null

    const parsed = JSON.parse(raw) as Partial<PersistedUser>
    if (
      !parsed ||
      typeof parsed.name !== "string" ||
      typeof parsed.email !== "string"
    ) {
      return null
    }

    return {
      name: parsed.name,
      email: parsed.email,
      avatar: typeof parsed.avatar === "string" ? parsed.avatar : undefined,
      plan: parsed.plan === "pro" ? "pro" : "free",
    }
  } catch {
    return null
  }
}

export async function syncProjectToBackend(project: Project): Promise<boolean> {
  if (typeof window === "undefined" || window.navigator?.onLine === false) {
    markProjectSyncPending(project.id)
    return false
  }

  const normalized = normalizeProject(project)
  const payload = {
    id: normalized.id,
    name: normalized.name,
    description: normalized.description,
    status: normalized.status,
    messages: normalized.messages,
    versions: normalized.versions,
    initialPrompt: normalized.initialPrompt,
    createdAt: normalized.createdAt,
    updatedAt: normalized.updatedAt,
    lastEdited: normalized.lastEdited,
    artifact: normalized.artifact,
    files: normalized.files,
    providerDiagnostics: normalized.providerDiagnostics,
    lastGeneration: normalized.lastGeneration,
    template: normalized.template,
  }

  try {
    const response = await fetch(
      `/api/projects/${encodeURIComponent(normalized.id)}`,
      {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        credentials: "same-origin",
        body: JSON.stringify(payload),
      },
    )
    // 401 = unauthenticated — do not queue for retry, it will never succeed
    // until the user signs in, at which point the session bootstrap re-syncs.
    if (response.status === 401) return false
    if (response.ok) clearProjectSyncPending(project.id)
    else markProjectSyncPending(project.id)
    return response.ok
  } catch {
    markProjectSyncPending(project.id)
    return false
  }
}

export async function retryPendingProjectSyncs(
  projects: Project[],
): Promise<number> {
  const projectsById = new Map(projects.map((project) => [project.id, project]))
  const pending = getPendingSyncProjectIds()
  const results = await Promise.all(
    pending.map((id) => {
      const project = projectsById.get(id)
      return project ? syncProjectToBackend(project) : Promise.resolve(false)
    }),
  )
  return results.filter(Boolean).length
}

