export interface ProjectRecord {
  id: string
  name: string
  description: string
  status: "LIVE" | "DRAFT" | "ARCHIVED"
  lastEdited: string
  updatedAt: string
  createdAt: string
  starred: boolean
  messages: Array<{
    id: string
    role: "user" | "assistant"
    content: string
    timestamp: string
