        const remoteDeployments = Array.isArray(body)
          ? body
          : Array.isArray(body?.deployments)
            ? body.deployments
            : []
        if (!mounted) return
        if (remoteDeployments.length > 0) {
          dispatch({
            type: "SET_DEPLOYMENT_RECORDS",
            payload: normalizeDeploymentRecords(
              remoteDeployments,
              DEFAULT_DEPLOYMENT_RECORDS,
