// ─── Types ────────────────────────────────────────────────────────────────────

export type { Project, ChatMessage, Version }

export interface Toast {
  id: string
  message: string
  type: "default" | "success" | "error"
  action?: { label: string onClick: () => void }
}

export interface Notification {
  id: string
  message: string
  read: boolean
  timestamp: string
  link?: string
}

export interface User {
  name: string
  email: string
  avatar?: string
  plan: "free" | "pro"
}

export type ModalType = "share" | "deploy" | "export" | "auth" | "confirm" | "settings" | "project-settings" | null

export interface ConfirmPayload {
  title: string
  description: string
  confirmLabel?: string
  onConfirm: () => void
}

export interface CreateProjectOptions {
  model?: string
  mode?: "plan" | "build"
  name?: string
  description?: string
  template?: ProjectTemplateOrigin
}

interface AppState {
  user: User | null
  projects: Project[]
  activeProjectId: string | null
  persistenceError: string | null
  modal: ModalType
  confirmPayload: ConfirmPayload | null
  toasts: Toast[]
  isCommandPaletteOpen: boolean
  isShortcutsOpen: boolean
  isProfileOpen: boolean
  isNotificationsOpen: boolean
  notifications: Notification[]
  isForge: boolean
  installedSkills: string[] // skill IDs
  enabledSkills: string[] // subset of installed that are active
  connectedConnectors: string[] // connector IDs
  deploymentRecords: DeploymentRecord[]
}

type Action = { type: "SET_USER" payload: User | null } | {
  type: "ADD_PROJECT"
  payload: Project
} | { type: "SET_PROJECTS" payload: Project[] } | {
  type: "UPDATE_PROJECT"
  payload: Partial<Project> & { id: string }
} | { type: "DELETE_PROJECT" payload: string } | {
  type: "STAR_PROJECT"
  payload: string
} | { type: "SET_ACTIVE_PROJECT" payload: string | null } | {
  type: "OPEN_MODAL"
  payload: ModalType
} | { type: "CLOSE_MODAL" } | {
  type: "SET_CONFIRM"
  payload: ConfirmPayload | null
} | { type: "PUSH_TOAST" payload: Toast } | {
  type: "REMOVE_TOAST"
  payload: string
} | { type: "TOGGLE_COMMAND_PALETTE" } | { type: "TOGGLE_SHORTCUTS" } | {
  type: "TOGGLE_PROFILE"
} | { type: "TOGGLE_NOTIFICATIONS" } | {
  type: "ADD_NOTIFICATION"
  payload: Notification
} | { type: "MARK_ALL_READ" } | { type: "START_FORGE" } | {
  type: "END_FORGE"
} | { type: "INSTALL_SKILL" payload: string } | {
  type: "UNINSTALL_SKILL"
  payload: string
} | { type: "ENABLE_SKILL" payload: string } | {
  type: "DISABLE_SKILL"
  payload: string
} | { type: "CONNECT_CONNECTOR" payload: string } | {
  type: "DISCONNECT_CONNECTOR"
  payload: string
} | { type: "ADD_DEPLOYMENT" payload: DeploymentRecord } | {
  type: "UPDATE_DEPLOYMENT"
  payload: Partial<DeploymentRecord> & { id: string }
} | { type: "SET_DEPLOYMENT_RECORDS" payload: DeploymentRecord[] }

const INITIAL_NOTIFICATIONS: Notification[] = []

const INITIAL: AppState = {
  user: null,
  projects: [],
  activeProjectId: null,
  persistenceError: null,
  modal: null,
  confirmPayload: null,
  toasts: [],
  isCommandPaletteOpen: false,
  isShortcutsOpen: false,
