import { useEffect, useRef, useState } from "react"
import { useApp } from "../store/AppContext"
import { savePersistedUser } from "../lib/persistence"
import { XIcon, ZapIcon } from "./icons"

import { auth } from "../lib/firebase/config"
import {
  signInWithPopup,
  GoogleAuthProvider,
  GithubAuthProvider,
  createUserWithEmailAndPassword,
  signInWithEmailAndPassword,
} from "firebase/auth"

interface Props {
  open: boolean
  onClose: () => void
}

type Tab = "signin" | "signup"

function applyServerUser(raw: Record<string, unknown>): User {
  return {
    name: typeof raw.name === "string" ? raw.name : "Builder",
    email: typeof raw.email === "string" ? raw.email : "",
    avatar: typeof raw.avatar === "string" ? raw.avatar : "",
    plan: raw.plan === "pro" ? "pro" : "free",
  }
}

export default function AuthSheet({ open, onClose }: Props) {
  const {
    setCurrentUser,
    projects,
    addToast,
    addNotification,
    loadServerProjects,
  } = useApp()
  const [tab, setTab] = useState<Tab>("signin")
  const [name, setName] = useState("")
  const [email, setEmail] = useState("")
  const [password, setPassword] = useState("")
  const [loading, setLoading] = useState(false)
  const [fieldError, setFieldError] = useState<string | null>(null)
  const firstFieldRef = useRef<HTMLInputElement>(null)

  // Reset form state when the sheet opens
  useEffect(() => {
    if (!open) return
    setFieldError(null)
    setLoading(false)
    setTimeout(() => firstFieldRef.current?.focus(), 60)
  }, [open, tab])

  // Escape dismissal
  useEffect(() => {
    if (!open) return
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose()
    }
    window.addEventListener("keydown", onKeyDown)
    return () => window.removeEventListener("keydown", onKeyDown)
  }, [open, onClose])

  if (!open) return null

  // ── Helpers ──────────────────────────────────────────────────────────────

  function validateSignIn(): string | null {
    if (!email.trim()) return "Email is required."
    if (!password) return "Password is required."
    return null
  }

  function validateSignUp(): string | null {
    if (!name.trim()) return "Name is required."
    if (!email.trim()) return "Email is required."
    if (password.length < 8) return "Password must be at least 8 characters."
    return null
  }

  function onSuccess(user: User) {
    setCurrentUser(user)
    savePersistedUser(user)
    addToast(`Welcome, ${user.name}`, "success")
    if (projects.length > 0) {
      addNotification(
        `${projects.length} project${
          projects.length > 1 ? "s are" : " is"
        } available in your workspace.`,
      )
    }
    // Fetch this user's server-side projects and merge into local state.
    void loadServerProjects()
    onClose()
  }

  // ── Sign-in ───────────────────────────────────────────────────────────────

  async function handleSignIn(e: React.FormEvent) {
    e.preventDefault()
    const err = validateSignIn()
    if (err) {
      setFieldError(err)
      return
    }
    setFieldError(null)
    setLoading(true)
    try {
      const result = await signInWithEmailAndPassword(
        auth,
        email.trim().toLowerCase(),
        password,
      )

      const realUser = {
        name: result.user.displayName || email.trim().split("@")[0],
        email: result.user.email || email.trim(),
        avatar:
          result.user.photoURL ||
          "https://lh3.googleusercontent.com/a/default-user",
        plan: "pro" as const,
      }
      onSuccess(realUser)
    } catch (err: any) {
      setFieldError(err.message || "Sign-in failed.")
    } finally {
      setLoading(false)
    }
  }

  // ── Sign-up ───────────────────────────────────────────────────────────────

  async function handleSignUp(e: React.FormEvent) {
    e.preventDefault()
    const err = validateSignUp()
    if (err) {
      setFieldError(err)
      return
    }
    setFieldError(null)
    setLoading(true)
    try {
      const result = await createUserWithEmailAndPassword(
        auth,
        email.trim().toLowerCase(),
        password,
      )

      const realUser = {
        name: name.trim(),
        email: result.user.email || email.trim(),
        avatar: "https://lh3.googleusercontent.com/a/default-user",
        plan: "pro" as const,
      }
      onSuccess(realUser)
    } catch (err: any) {
      setFieldError(err.message || "Sign-up failed.")
    } finally {
      setLoading(false)
    }
  }

  // ── Shared input style ────────────────────────────────────────────────────

  const inputStyle: React.CSSProperties = {
    background: "var(--surface-2)",
    border: "1px solid var(--border-default)",
    color: "var(--text-primary)",
    fontFamily: "var(--font-geist)",
    borderRadius: 8,
    padding: "9px 12px",
    fontSize: 13,
    width: "100%",
    outline: "none",
  }

  // ── Render ────────────────────────────────────────────────────────────────

  return (
    <div className="fixed inset-0 z-[100] flex items-end sm:items-center justify-center p-4">
      <div
        className="absolute inset-0"
        style={{ background: "rgba(0,0,0,0.72)", backdropFilter: "blur(6px)" }}
        onClick={onClose}
      />
      <div
        className="relative rounded-2xl w-full overflow-hidden"
        role="dialog"
        aria-modal="true"
        aria-labelledby="auth-sheet-title"
        style={{
          maxWidth: 400,
          background: "rgba(18,18,18,0.97)",
          backdropFilter: "blur(24px)",
          border: "1px solid rgba(255,255,255,0.08)",
          boxShadow:
            "0 32px 80px rgba(0,0,0,0.7), 0 0 0 1px rgba(255,255,255,0.03)",
          animation: "shango-panel-enter 0.24s cubic-bezier(0.16,1,0.3,1)",
        }}
      >
        {/* Header */}
        <div className="flex items-start justify-between p-6 pb-4">
          <div>
            <ZapIcon
              size={20}
              className="mb-3"
              style={{ color: "var(--text-primary)" }}
            />
            <h2
              id="auth-sheet-title"
              className="text-lg font-semibold"
              style={{
                color: "var(--text-primary)",
                fontFamily: "var(--font-geist)",
                letterSpacing: "-0.01em",
              }}
            >
              {tab === "signin" ? "Welcome back" : "Create your account"}
            </h2>
            <p
              className="text-sm mt-1"
              style={{
                color: "var(--text-muted)",
                fontFamily: "var(--font-geist)",
                lineHeight: 1.55,
              }}
            >
              {tab === "signin"
                ? "Sign in to access your projects."
                : "Your work lives here. Build something meaningful."}
            </p>
          </div>
          <button
            onClick={onClose}
            aria-label="Close"
            className="p-1 rounded-md"
            style={{ color: "var(--text-muted)" }}
          >
            <XIcon size={14} />
          </button>
        </div>

        {/* Tab switcher */}
        <div
          className="flex mx-6 mb-4 rounded-lg overflow-hidden"
          style={{
            background: "var(--surface-2)",
            border: "1px solid var(--border-subtle)",
          }}
          role="tablist"
        >
          {(["signin", "signup"] as Tab[]).map((t) => (
            <button
              key={t}
              role="tab"
              aria-selected={tab === t}
              onClick={() => {
                setTab(t)
                setFieldError(null)
              }}
              className="flex-1 py-2 text-xs font-medium transition-colors"
              style={{
                fontFamily: "var(--font-geist)",
                background: tab === t ? "var(--surface-4)" : "transparent",
                color: tab === t ? "var(--text-primary)" : "var(--text-muted)",
                borderRadius: 6,
                margin: 2,
              }}
            >
              {t === "signin" ? "Sign in" : "Create account"}
            </button>
          ))}
        </div>

        {/* Form */}
        <form
          onSubmit={tab === "signin" ? handleSignIn : handleSignUp}
          className="px-6 pb-6 flex flex-col gap-3"
          noValidate
        >
          {tab === "signup" && (
            <div>
              <label
                htmlFor="auth-name"
                className="block text-xs mb-1.5"
                style={{
                  color: "var(--text-muted)",
