import { useEffect, useRef, useState } from "react"
import { useApp } from "../store/AppContext"
import { savePersistedUser } from "../lib/persistence"
import { XIcon, ZapIcon } from "./icons"

import { auth } from "../lib/firebase/config"
import {
  signInWithPopup,
  GoogleAuthProvider,
  GithubAuthProvider,
  createUserWithEmailAndPassword,
  signInWithEmailAndPassword,
} from "firebase/auth"

interface Props {
  open: boolean
  onClose: () => void
}

type Tab = "signin" | "signup"

function applyServerUser(raw: Record<string, unknown>): User {
  return {
    name: typeof raw.name === "string" ? raw.name : "Builder",
    email: typeof raw.email === "string" ? raw.email : "",
    avatar: typeof raw.avatar === "string" ? raw.avatar : "",
    plan: raw.plan === "pro" ? "pro" : "free",
  }
}

export default function AuthSheet({ open, onClose }: Props) {
  const {
    setCurrentUser,
    projects,
    addToast,
    addNotification,
    loadServerProjects,
  } = useApp()
  const [tab, setTab] = useState<Tab>("signin")
  const [name, setName] = useState("")
  const [email, setEmail] = useState("")
  const [password, setPassword] = useState("")
  const [loading, setLoading] = useState(false)
  const [fieldError, setFieldError] = useState<string | null>(null)
  const firstFieldRef = useRef<HTMLInputElement>(null)

  // Reset form state when the sheet opens
  useEffect(() => {
    if (!open) return
    setFieldError(null)
    setLoading(false)
    setTimeout(() => firstFieldRef.current?.focus(), 60)
  }, [open, tab])

  // Escape dismissal
  useEffect(() => {
    if (!open) return
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose()
    }
    window.addEventListener("keydown", onKeyDown)
    return () => window.removeEventListener("keydown", onKeyDown)
  }, [open, onClose])

  if (!open) return null

  // ── Helpers ──────────────────────────────────────────────────────────────

  function validateSignIn(): string | null {
    if (!email.trim()) return "Email is required."
    if (!password) return "Password is required."
    return null
  }

  function validateSignUp(): string | null {
    if (!name.trim()) return "Name is required."
    if (!email.trim()) return "Email is required."
    if (password.length < 8) return "Password must be at least 8 characters."
    return null
  }

  function onSuccess(user: User) {
    setCurrentUser(user)
    savePersistedUser(user)
    addToast(`Welcome, ${user.name}`, "success")
    if (projects.length > 0) {
      addNotification(
        `${projects.length} project${
          projects.length > 1 ? "s are" : " is"
        } available in your workspace.`,
      )
    }
    // Fetch this user's server-side projects and merge into local state.
    void loadServerProjects()
    onClose()
  }

  // ── Sign-in ───────────────────────────────────────────────────────────────

  async function handleSignIn(e: React.FormEvent) {
    e.preventDefault()
    const err = validateSignIn()
    if (err) {
      setFieldError(err)
      return
    }
    setFieldError(null)
    setLoading(true)
    try {
      const result = await signInWithEmailAndPassword(
        auth,
        email.trim().toLowerCase(),
        password,
      )

      const realUser = {
        name: result.user.displayName || email.trim().split("@")[0],
        email: result.user.email || email.trim(),
        avatar:
          result.user.photoURL ||
          "https://lh3.googleusercontent.com/a/default-user",
        plan: "pro" as const,
      }
      onSuccess(realUser)
    } catch (err: any) {
      setFieldError(err.message || "Sign-in failed.")
    } finally {
      setLoading(false)
    }
  }

  // ── Sign-up ───────────────────────────────────────────────────────────────

  async function handleSignUp(e: React.FormEvent) {
    e.preventDefault()
    const err = validateSignUp()
    if (err) {
      setFieldError(err)
      return
    }
    setFieldError(null)
    setLoading(true)
    try {
      const result = await createUserWithEmailAndPassword(
        auth,
        email.trim().toLowerCase(),
        password,
      )

      const realUser = {
        name: name.trim(),
        email: result.user.email || email.trim(),
        avatar: "https://lh3.googleusercontent.com/a/default-user",
        plan: "pro" as const,
      }
      onSuccess(realUser)
    } catch (err: any) {
      setFieldError(err.message || "Sign-up failed.")
    } finally {
      setLoading(false)
    }
  }

  // ── Shared input style ────────────────────────────────────────────────────

